"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[5899],{5395:(e,a,i)=>{i.d(a,{G:()=>r});let n={bled:{tagline:"La perla delle Alpi con castello medievale e isola",description:"Il lago di Bled, con la sua isola unica su cui sorgono chiesa e campanile, \xe8 la pi\xf9 celebre cartolina slovena. Il castello medievale sulla roccia offre viste panoramiche, la vicina gola di Vintgar invita a una breve passeggiata nel calcare lungo un fiume tranquillo. Una fetta di kremšnita in pasticceria sul lago \xe8 il dolce peccato obbligato.",highlights:["Isola di Bled","Castello di Bled","Gola di Vintgar","Kremšnita"],activities:["Giro in pletna all'isola","Visita al castello","Passeggiata nella gola","Nuoto"],duration:"1-2 giorni"},bohinj:{tagline:"Bellezza selvaggia e intatta del Parco nazionale del Triglav",description:"Il lago di Bohinj \xe8 il fratello maggiore e pi\xf9 selvaggio del lago di Bled, interamente dentro il Parco nazionale del Triglav. La funivia del Vogel offre viste panoramiche sulle Alpi Giulie, la cascata Savica \xe8 a breve cammino nel bosco. Ideale per chi cerca tranquillit\xe0 e una fuga attiva nella natura.",highlights:["Lago di Bohinj","Vogel","Cascata Savica","Parco nazionale del Triglav"],activities:["Escursionismo","Sci","Kayak","Funivia del Vogel"],duration:"1-2 giorni"},ljubljana:{tagline:"Capitale verde e creativa con il ponte del drago",description:"Lubiana \xe8 una capitale piccola ma vivace, dove l'architettura medievale si mescola con una scena gastronomica contemporanea. Il castello offre una vista panoramica, piazza Prešeren con il ponte del drago \xe8 il cuore della citt\xe0 e lungo la Ljubljanica si snoda la vita di caff\xe8 e chiacchiere.",highlights:["Castello di Lubiana","Ponte del drago","Piazza Prešeren","Parco Tivoli"],activities:["Visita al castello","Passeggiata nel centro storico","Tour gastronomico","Bici lungo la Ljubljanica"],duration:"2 giorni"},postojna:{tagline:"24 km di gallerie sotterranee e un regno fatato di stalattiti",description:"La grotta di Postumia \xe8 il pi\xf9 grande sistema carsico turistico d'Europa, con un unico trenino sotterraneo. Vi abitava anche il proteo — l'endemita che ha ispirato le leggende sui cuccioli di drago. Il castello di Predjama, scavato in una parete di 123 metri, \xe8 a soli 9 km.",highlights:["Trenino sotterraneo","Stalattiti","Proteo","Castello di Predjama"],activities:["Tour della grotta in trenino","Visita al castello di Predjama","Fotografia"],duration:"1 giorno"},piran:{tagline:"La Venezia slovena con vicoli di pietra e piazza Tartini",description:"Pirano \xe8 una cittadina marinara dall'aspetto veneziano, dove i vicoli stretti si stringono tra case di pietra. Piazza Tartini, dai pavimenti marmorei, \xe8 dedicata al violinista Giuseppe Tartini. La chiesa di San Giorgio sul colle domina il mare Adriatico.",highlights:["Piazza Tartini","Chiesa di San Giorgio","Lungomare","Vecchi vicoli"],activities:["Passeggiata nel centro storico","Tramonto","Pesce fresco","Visita alle saline"],duration:"1 giorno"},soca:{tagline:"Il fiume smeraldo tra le Alpi Giulie per avventure adrenaliniche",description:"L'Isonzo \xe8 uno dei pochi fiumi che mantiene il suo colore smeraldo tutto l'anno. Si snoda attraverso Tolmino e Plezzo, offrendo rafting, kayak e canyoning di prima classe. Lungo il percorso le gole dell'Isonzo — piscine naturali scavate nel calcare, ideali per rinfrescarsi d'estate.",highlights:["Gole dell'Isonzo","Plezzo","Tolmino","Fortezza Kluže"],activities:["Rafting","Kayak","Canyoning","Zip-line"],duration:"2-3 giorni"},triglav:{tagline:"2864 m, simbolo della nazione con innumerevoli sentieri",description:"Il Triglav \xe8 la cima pi\xf9 alta della Slovenia e simbolo nazionale, presente nello stemma. L'ascesa richiede escursionismo tecnico, ma con buona preparazione \xe8 raggiungibile in uno o due giorni. In cima sta la torre Aljaž — il rifugio pi\xf9 alto del paese.",highlights:["Vetta a 2864 m","Torre Aljaž","Fiore del Triglav","Escursionismo"],activities:["Escursionismo","Alpinismo","Fotografia"],duration:"2 giorni"},kobarid:{tagline:"Storia, Fronte dell'Isonzo e gastronomia in un solo paese",description:"Caporetto \xe8 un paesino sull'Isonzo, celebre per il Museo di Caporetto che documenta la cruenta Fronte dell'Isonzo della Prima guerra mondiale. Il ponte di Napoleone e il Kolovrat offrono viste panoramiche. Hiša Franko, uno dei migliori ristoranti della regione, propone la cucina tolminiana contemporanea.",highlights:["Museo di Caporetto","Ponte di Napoleone","Kolovrat","Hiša Franko"],activities:["Museo","Escursionismo","Esperienza gastronomica","Bici lungo l'Isonzo"],duration:"1 giorno"},maribor:{tagline:"La seconda citt\xe0 con la vite pi\xf9 antica del mondo",description:"Maribor si trova sulla Drava, circondata dai vigneti del Pohorje. La Vecchia Vite, vecchia di oltre 400 anni, \xe8 iscritta nel Guinness dei primati. La citt\xe0 offre un vivace centro storico, i filari del Pohorje e lo sci in inverno.",highlights:["La Vecchia Vite","Pohorje","Piazza principale","Viticoltura"],activities:["Visita alla Vecchia Vite","Sci sul Pohorje","Degustazione di vini","Centro storico"],duration:"1-2 giorni"},portoroz:{tagline:"La localit\xe0 balneare slovena con casin\xf2 e wellness",description:"Portorose \xe8 la localit\xe0 balneare slovena pi\xf9 celebre, con una lunga spiaggia sabbiosa, hotel con centri benessere e il casin\xf2. La passeggiata a mare collega Portorose a Pirano, le saline di Sicciole offrono un'esperienza naturale unica e il fango terapeutico.",highlights:["Spiaggia","Casin\xf2","Saline di Sicciole","Wellness"],activities:["Nuoto","Wellness","Giochi d'azzardo","Bici lungo il mare"],duration:"2-3 giorni"},vintgar:{tagline:"Una breve passeggiata nel calcare lungo un fiume tranquillo",description:"La gola di Vintgar \xe8 una gola di 1,6 km lungo il fiume Radovna, a soli 4 km da Bled. I ponti di legno accompagnano lungo acque cristalline, passando una cascata e vasche naturali. La passeggiata dura circa un'ora ed \xe8 adatta a tutte le et\xe0.",highlights:["Cascata Šum","Ponti di legno","Acqua cristallina","Vasche naturali"],activities:["Passeggiata","Fotografia","Osservazione della natura"],duration:"1 giorno"},rogaska:{tagline:"La pi\xf9 antica stazione termale slovena con acqua minerale",description:"Rogaška Slatina \xe8 un'elegante localit\xe0 termale con 400 anni di tradizione, celebre per l'acqua minerale Donat Mg con il pi\xf9 alto contenuto di magnesio al mondo. L'architettura liberty, i parchi e i centri benessere offrono relax tutto l'anno.",highlights:["Donat Mg","Architettura liberty","Grand Hotel","Wellness"],activities:["Wellness","Degustazione di acqua minerale","Passeggiate nel parco","Massaggi"],duration:"2 giorni"},ptuj:{tagline:"La citt\xe0 pi\xf9 antica della Slovenia con storia romana",description:"Ptuj \xe8 la citt\xe0 documentata pi\xf9 antica della Slovenia, fondata in epoca romana come Poetovio. Il castello medievale sul colle offre una vista panoramica sulla Drava, il centro storico conserva l'architettura barocca. Celebre per il Kurentovanje — il pi\xf9 grande carnevale dell'Europa centrale.",highlights:["Castello di Ptuj","Reperti romani","Kurentovanje","Drava"],activities:["Visita al castello","Passeggiata nel centro storico","Festival di carnevale","Passeggiata lungo la Drava"],duration:"1 giorno"},celje:{tagline:"L'antica capitale dei conti di Celje con un castello imponente",description:"Celje \xe8 la terza citt\xe0 della Slovenia, celebre per il castello medievale dei conti di Celje — un tempo la casata nobiliare pi\xf9 influente delle terre slovene. La piazza vecchia conserva facciate barocche, lungo la Savinja si snoda un percorso di passeggio.",highlights:["Castello vecchio di Celje","Piazza vecchia","Savinja","Museo regionale"],activities:["Visita al castello","Passeggiata nel centro storico","Museo","Bici lungo la Savinja"],duration:"1 giorno"},"nova-gorica":{tagline:"La citt\xe0 delle rose al confine con l'Italia",description:"Nova Gorica \xe8 una citt\xe0 giovane costruita dopo la Seconda guerra mondiale, nota come 'citt\xe0 delle rose'. Confina con Gorizia italiana — le uniche citt\xe0 europee che condividono una piazza (Piazza Europa). Casin\xf2, parchi e clima mediterraneo.",highlights:["Piazza Europa","Parco delle rose","Casin\xf2 Perla","Ponte di Salcano"],activities:["Passeggiata nel parco","Giochi d'azzardo","Passeggiata al confine in Italia","Bici lungo l'Isonzo"],duration:"1 giorno"},"slovenj-gradec":{tagline:"Cittadina alpina con ricca tradizione musicale",description:"Slovenj Gradec \xe8 una storica cittadina nel nord della Slovenia, circondata dalle Alpi Carinziane. Celebre per la Sala dei musicisti sloveni e come citt\xe0 natale di Hugo Wolf. Punti di partenza ideali per escursioni sul Pohorje e sull'Uršlja gora.",highlights:["Sala dei musicisti sloveni","Piazza vecchia","Pohorje","Uršlja gora"],activities:["Escursionismo","Concerti","Passeggiata nel centro storico","Sci"],duration:"1 giorno"},dravograd:{tagline:"Il confluenza dei fiumi Drava, Meža e Mislinja",description:"Dravograd \xe8 una piccola cittadina nel nord della Slovenia dove si incontrano tre fiumi — Drava, Meža e Mislinja. Circondata dai boschi del Kozjak e del Pohorje. Central idroelettrica sulla Drava e sentieri lungo il fiume.",highlights:["Confluenza dei tre fiumi","Idroelettrica di Dravograd","Kozjak","Escursionismo"],activities:["Escursionismo","Pesca","Bici lungo la Drava","Fotografia naturalistica"],duration:"1 giorno"},"murska-sobota":{tagline:"Il centro della Prekmurja con castello sul lago",description:"Murska Sobota \xe8 il centro della Prekmurja — la piatta campagna pannonica del nordest sloveno. Il castello di Murska Sobota affianco al lago omonimo ospita il Museo regionale. Celebre per la gibanica prekmurska e l'olio di zucca.",highlights:["Castello di Murska Sobota","Lago di Sobota","Gibanica prekmurska","Museo regionale"],activities:["Visita al castello","Passeggiata along il lago","Esperienze gastronomiche","Bici in pianura"],duration:"1 giorno"},lendava:{tagline:"Citt\xe0 bilingue con vigneti e castello sul colle",description:"Lendava \xe8 la citt\xe0 pi\xf9 orientale della Slovenia, al confine con l'Ungheria. Citt\xe0 bilingue (sloveno-ungherese) con un castello sul colle che offre una vista panoramica sui vigneti dei colli di Lendava. Produzione di vini bianchi di prima classe.",highlights:["Castello di Lendava","Vigneti dei colli di Lendava","Cultura bilingue","Cantina"],activities:["Degustazione di vini","Visita al castello","Bici tra i vigneti","Passeggiata di confine"],duration:"1 giorno"},"novo-mesto":{tagline:"La capitale della Dolenjska sul fiume Krka",description:"Novo mesto \xe8 il centro della Dolenjska, costruita nell'ansa del fiume Krka. La piazza vecchia con la via principale conserva il carattere medievale. Celebre per il cviček — il vino tradizionale della Dolenjska — e per i reperti archeologici della cultura di Hallstatt.",highlights:["Piazza vecchia","Fiume Krka","Cviček","Museo archeologico"],activities:["Passeggiata nel centro storico","Degustazione di vini","Bici lungo la Krka","Museo"],duration:"1-2 giorni"},otocec:{tagline:"L'unico castello sloveno su un'isola fluviale",description:"Otočec \xe8 l'unico castello sloveno su un'isola, circondato dal fiume Krka. Oggi hotel di lusso con campo da golf e wellness. Ambiente romantico per coppie e punto di partenza per il cicloturismo lungo la Krka.",highlights:["Castello sull'isola","Fiume Krka","Golf","Wellness"],activities:["Golf","Wellness","Bici lungo la Krka","Cena romantica"],duration:"1-2 giorni"},crnomelj:{tagline:"Il cuore della Bela krajina sul fiume Kolpa",description:"Črnomelj \xe8 il centro della Bela krajina — un paesaggio caldo e mediterraneo nel sud-est della Slovenia lungo il fiume Kolpa. Celebre per la pisanica della Bela krajina (uova colorate), gli steljniki e la musica tradizionale. La Kolpa offre l'acqua pi\xf9 calda per il bagno in Slovenia.",highlights:["Fiume Kolpa","Piazza vecchia","Pisanica della Bela krajina","Steljniki"],activities:["Bagno nella Kolpa","Passeggiata nel centro storico","Bici nella Bela krajina","Museo etnografico"],duration:"1-2 giorni"},zagreb:{tagline:"Capitale croata con fascino viennese e cultura dei caff\xe8",description:"Zagabria \xe8 una citt\xe0 al confine tra Europa centrale e sudorientale, con un nucleo simile a Vienna: la Citt\xe0 alta con il mercato coperto e la torre Lotrščak, le strade liberty della citt\xe0 bassa e il vivace Dolac al mattino, quando i contadini espongono i loro prodotti. L'Avvento in Citt\xe0 alta a dicembre \xe8 tra i pi\xf9 festosi d'Europa, d'estate il caff\xe8 in via Tkalčićeva d\xe0 il ritmo alla citt\xe0.",highlights:["Citt\xe0 alta","Piazza Ban Jelačić","Mercato Dolac","Cattedrale"],activities:["Passeggiata nella Citt\xe0 alta","Musei e gallerie","Avvento a dicembre","Caff\xe8 in Tkalčićeva"],duration:"2 giorni"},"plitvicka-jezera":{tagline:"Cascata UNESCO di laghi turchesi e cascate",description:"Il pi\xf9 antico parco nazionale croato \xe8 una catena di sedici laghi che si riversano l'uno nell'altro oltre dighe travertinose e cascate. Le passerelle di legno accompagnano lungo l'acqua attraverso il bosco, sul lago pi\xf9 grande, il Kozjak, navigano barche elettriche. Il colore dell'acqua oscilla tra turchese e smeraldo secondo stagione e luce.",highlights:["Grande cascata","Lago Kozjak","Passerelle di legno","Barriere travertinose"],activities:["Passeggiata sulle passerelle","Giro in barca sul Kozjak","Fotografia","Visione della Grande cascata"],duration:"1 giorno"},rijeka:{tagline:"Capitale della cultura con il pi\xf9 grande porto croato",description:"Fiume \xe8 una citt\xe0 portuale sul Quarnaro con un nucleo asburgico, il lungo Korzo e il castello di Tersatto sul colle sopra la citt\xe0. Nel 2020 \xe8 stata capitale europea della cultura; il Carnevale di Fiume a Pasqua \xe8 tra i pi\xf9 grandi d'Europa. Da Fiume partono traghetti per le isole e l'Italia — la citt\xe0 \xe8 la porta del Quarnaro.",highlights:["Korzo","Castello di Tersatto","Torre civica","Cattedrale di San Vito"],activities:["Passeggiata sul Korzo","Vista da Tersatto","Carnevale di Fiume","Escursioni in traghetto alle isole"],duration:"1-2 giorni"},pula:{tagline:"Anfiteatro romano sul mare Adriatico",description:"Pola \xe8 la citt\xe0 pi\xf9 grande dell'Istria con l'anfiteatro romano meglio conservato del mondo dopo Roma — l'Arena del I secolo ospita ancora concerti e cinema all'aperto. Il centro storico con l'Arco d'oro e la Cattedrale di Santa Maria si stringe sulla penisola, attorno alla citt\xe0 si distendono spiagge e villaggi vitivinicoli istriani.",highlights:["Anfiteatro Arena","Arco d'oro","Piazza vecchia","Riviera istriana"],activities:["Visita all'Arena","Passeggiata nel centro storico","Bagno","Degustazioni di vini in Istria"],duration:"1-2 giorni"},zadar:{tagline:"La citt\xe0 del tramonto e dell'organo di mare",description:"Zara \xe8 una citt\xe0 dalmata su una penisola con impianto romano e la chiesa romanica di San Donato. Sulla costa l'organo di mare suona con le onde, accanto il Saluto al sole — un'installazione attorno alla quale si raccolgono le folle al tramonto; Alfred Hitchcock defin\xec il tramonto di Zara il pi\xf9 bello del mondo. Da Zara partono le escursioni pi\xf9 brevi per le Kornati.",highlights:["Organo di mare","Saluto al sole","Chiesa di San Donato","Rovine romane"],activities:["Ascolto dell'organo di mare","Tramonto","Passeggiata sulle mura","Escursione alle Kornati"],duration:"1-2 giorni"},split:{tagline:"Citt\xe0 viva dentro il palazzo di Diocleziano",description:"Il cuore di Spalato \xe8 il palazzo di Diocleziano del IV secolo — un complesso romano in cui oggi vive la gente: caff\xe8 nel Peristilio, mercati nei sotterranei, boutique nelle sale voltate. La cattedrale di San Doimo \xe8 la pi\xf9 antica cattedrale al mondo in uso continuo. Il colle Marjan offre una fuga tra i pini sopra la citt\xe0, dal porto salpano traghetti per le isole.",highlights:["Palazzo di Diocleziano","Peristilio","Cattedrale di San Doimo","Marjan"],activities:["Esplorazione del palazzo","Passeggiata sul Marjan","Spiaggia Bačvice","Traghetti verso le isole"],duration:"2 giorni"},hvar:{tagline:"L'isola adriatica pi\xf9 soleggiata di lavanda e pietra",description:"Hvar \xe8 un'isola con quasi 2800 ore di sole l'anno, una cittadina portuale dall'aspetto veneziano e la fortezza Fortica sul colle. L'interno nasconde campi di lavanda e vigneti della bogotinjava pošipina (vitigno autoctono). Davanti al porto stanno le isole Pakleni — calette di scisto per ancoraggi e bagni.",highlights:["Fortezza Fortica","Porto di Hvar","Isole Pakleni","Campi di lavanda"],activities:["Vista dalla Fortica","Escursione alle isole Pakleni","Degustazione di pošip","Bagno nelle calette"],duration:"2-3 giorni"},dubrovnik:{tagline:"Citt\xe0 medievale cinta di mura sopra l'azzurro Adriatico",description:"Ragusa — la repubblica che per secoli gareggi\xf2 con Venezia — \xe8 una citt\xe0 murata sulla scogliera sul mare, il cui Stradun collega le porte Pile e Ploče. Le mura lunghe quasi due chilometri offrono la passeggiata urbana pi\xf9 celebre dell'Adriatico; la funivia sale sul Monte Srđ per la vista sulla citt\xe0 vecchia e le isole. Davanti alla citt\xe0 si stende l'boscosa isola di Lokrum.",highlights:["Mura cittadine","Stradun","Isola di Lokrum","Funivia sul Srđ"],activities:["Passeggiata sulle mura","Chiostro francescano","Escursione a Lokrum","Tramonto dal Srđ"],duration:"2-3 giorni"},kotor:{tagline:"Una baia simile a un fiordo con citt\xe0 medievale murata",description:"Cattaro siede sul fondo delle Bocche di Cattaro, che si attorcigliano tra monti ripidi come unico fiordo del Mediterraneo. Il centro storico con la rete di piazze e vicoli \xe8 protetto UNESCO; le mura con la fortezza San Giovanni salgono oltre 1200 scalini sopra la citt\xe0 e offrono una vista leggendaria sulla baia. Nella vicina Perasto sta l'isola barocca Gospa od Škrpjela.",highlights:["Citt\xe0 vecchia di Cattaro","Mura di San Giovanni","Bocche di Cattaro","Perasto"],activities:["Passeggiata nella citt\xe0 vecchia","Salita sulle mura","Escursione a Perasto","Croccata delle Bocche"],duration:"1-2 giorni"},budva:{tagline:"Citt\xe0 vecchia su una penisola tra spiagge e pini",description:"Budua \xe8 la localit\xe0 balneare montenegrina pi\xf9 visitata — centro storico su una penisola rocciosa con mura, attorno una serie di spiagge (Mogren, Jaz, Spiaggia slovena). D'estate strade e terrazze sono piene, in autunno e primavera la citt\xe0 vecchia respira tranquilla. Il soggetto pi\xf9 celebre per i fotografi \xe8 l'isoletta Santo Stefano con l'antico borgo-hotel.",highlights:["Citt\xe0 vecchia di Budua","Spiaggia Mogren","Santo Stefano","Spiaggia Jaz"],activities:["Passeggiata nella citt\xe0 vecchia","Bagno al Mogren","Vista su Santo Stefano","Serate sul lungomare"],duration:"1-2 giorni"},podgorica:{tagline:"Capitale rilassata al crocevia di fiumi e montagne",description:"Podgorica \xe8 la capitale e citt\xe0 pi\xf9 grande del Montenegro, costruita alla confluenza della Morača e della Ribnica. Il ritmo lo danno il korzo, le terrazze dei caff\xe8 e il Ponte del Millennio; Stara Varoš conserva resti ottomani con la torre dell'orologio. Ottimo punto di partenza — il lago di Scutari, Budua e il Durmitor sono escursioni quotidiane.",highlights:["Ponte del Millennio","Stara Varoš","Torre dell'orologio","Gorica"],activities:["Passeggiata sul korzo","Esplorazione della Stara Varoš","Caff\xe8 sulla Morača","Escursione al lago di Scutari"],duration:"1 giorno"},durmitor:{tagline:"Montagne UNESCO sopra il Lago Nero e il canyon della Tara",description:"Il parco nazionale del Durmitor \xe8 un massiccio costellato di 18 laghi glaciali — il pi\xf9 celebre \xe8 il Lago Nero accanto a Žabljak, capitale di montagna. Il canyon del fiume Tara \xe8 il pi\xf9 profondo d'Europa (1300 m) e sede del rafting tra le rive; la panoramica strada del Sedlo Soa collega Žabljak con il sud. D'inverno piste da sci, d'estate sentieri attorno ai laghi.",highlights:["Lago Nero","Canyon della Tara","Žabljak","Sedlo Soa"],activities:["Trekking attorno al Lago Nero","Rafting sulla Tara","Panoramica del Sedlo","Sci d'inverno"],duration:"2-3 giorni"},tirana:{tagline:"Capitale colorata con nucleo ottomano e ritmo da caff\xe8",description:"Tirana \xe8 una capitale che dopo lunghi decenni si \xe8 aperta — facciate colorate, piazza Scanderbeg con la moschea Et'hem Bej e la torre dell'orologio, caff\xe8 nelle strade dei blocchi. La funivia Dajti Ekspres sale a 1600 m sopra la citt\xe0 per la vista sulla pianura e l'Adriatico; il museo Bunk'Art in un rifugio atomico racconta il Novecento.",highlights:["Piazza Scanderbeg","Moschea Et'hem Bej","Bunk'Art","Monte Dajti"],activities:["Esplorazione del centro","Funivia sul Dajti","Musei","Cultura dei caff\xe8"],duration:"2 giorni"},berat:{tagline:"La citt\xe0 delle mille finestre sotto il castello sull'Osum",description:"Berat \xe8 una citt\xe0 protetta UNESCO, celebre come citt\xe0 delle mille finestre — le bianche case ottomane del quartiere Mangalem salgono a gradinate verso il castello in cima. Il vecchio ponte sul fiume Osum collega il quartiere Gorica; nel castello sta il Museo Onufri con le icone. Attorno a Berat vigneti, con degustazioni nelle case tradizionali.",highlights:["Castello di Berat","Quartiere Mangalem","Vecchio ponte","Museo Onufri"],activities:["Passeggiata nel Mangalem","Visita al castello","Ponte sull'Osum","Degustazione di vini"],duration:"1 giorno"},gjirokaster:{tagline:"La citt\xe0 di pietra — tetti grigi sotto un castello possente",description:"Gjirokast\xebr \xe8 una citt\xe0 UNESCO di case in pietra con tetti in scandole, arroccata su un pendio ripido sotto uno dei pi\xf9 grandi castelli dei Balcani. Il vecchio bazar conserva la strada mercantile ottomana con i suoi portici; la casa natale dello scrittore Ismail Kadare \xe8 oggi museo. Sulla valle aleggia la leggenda di Zerm e delle ninfe — le montagne attorno invitano alle escursioni.",highlights:["Castello di Gjirokast\xebr","Vecchio bazar","Case di pietra","Casa di Kadare"],activities:["Visita al castello","Passeggiata nel bazar","Museo etnografico","Escursionismo nei dintorni"],duration:"1 giorno"},saranda:{tagline:"Citt\xe0 soleggiata dello Ionio di fronte a Corf\xf9",description:"Saranda \xe8 la citt\xe0 balneare albanese pi\xf9 meridionale, di fronte alla greca Corf\xf9 (traghettata di 30 min). La costa a sud della citt\xe0 nasconde Ksamil con spiagge bianche e isolette, l'interno l'antichit\xe0 — Butrinto \xe8 una citt\xe0 antica UNESCO tra lago e canale. La vista dalla fortezza L\xebkur\xebsi sopra la citt\xe0 regala al tramonto il sole sul mar Ionio.",highlights:["Ksamil","Antica Butrinto","Fortezza L\xebkur\xebsi","Vista su Corf\xf9"],activities:["Bagno a Ksamil","Visita a Butrinto","Tramonto da L\xebkur\xebsi","Traghettata per Corf\xf9"],duration:"2-3 giorni"}};function r(e){return n[e]??null}},41353:(e,a,i)=>{i.d(a,{U:()=>r});let n={bled:{tagline:"Die Perle der Alpen mit mittelalterlicher Burg und Insel",description:"Der Bleder See mit seiner einzigartigen Insel, auf der Kirche und Glockenturm stehen, ist Sloweniens ber\xfchmteste Postkartenansicht. Die mittelalterliche Burg auf dem Fels bietet Panoramablicke, die nahe Vintgar-Klamm l\xe4dt zu einem kurzen Spaziergang durch den Kalkstein an einem ruhigen Fluss ein. Ein St\xfcck Bleder Cremeschnitte (kremšnita) in einer Seeb\xe4ckerei ist das Pflichts\xfcndchen.",highlights:["Bleder Insel","Burg Bled","Vintgar-Klamm","Cremeschnitte"],activities:["Pletna-Fahrt zur Insel","Burgbesuch","Klammspaziergang","Schwimmen"],duration:"1–2 Tage"},bohinj:{tagline:"Wilde, unber\xfchrte Sch\xf6nheit des Triglav-Nationalparks",description:"Der Bohinjer See ist der gr\xf6\xdfere, wildere Bruder des Bleder Sees, vollst\xe4ndig im Triglav-Nationalpark. Die Vogel-Seilbahn bietet Panoramablicke auf die Julischen Alpen, der Savica-Wasserfall liegt einen kurzen Waldweg entfernt. Ideal f\xfcr alle, die Ruhe und eine aktive Flucht in die Natur suchen.",highlights:["Bohinjer See","Vogel","Savica-Wasserfall","Triglav-Nationalpark"],activities:["Wandern","Skifahren","Kajak","Vogel-Seilbahn"],duration:"1–2 Tage"},ljubljana:{tagline:"Gr\xfcne, kreative Hauptstadt mit der Drachenbr\xfccke",description:"Ljubljana ist eine kleine, aber lebendige Hauptstadt, in der sich mittelalterliche Architektur und eine moderne Kulinarik-Szene mischen. Die Burg bietet Panoramablick, die Prešeren-Platz mit der Drachenbr\xfccke ist das Herz der Stadt, an der Ljubljanica entfaltet sich Kaffee und Gespr\xe4ch.",highlights:["Burg Ljubljana","Drachenbr\xfccke","Prešeren-Platz","Park Tivoli"],activities:["Burgbesuch","Altstadtrundgang","Kulinarik-Tour","Rad an der Ljubljanica"],duration:"2 Tage"},postojna:{tagline:"24 km unterirdische G\xe4nge und ein M\xe4rchenreich der Tropfsteine",description:"Die Postojna-H\xf6hle ist das gr\xf6\xdfte touristische H\xf6hlensystem Europas mit einer einzigartigen unterirdischen Bahn. Hier lebte auch der Grottenolm — das Endemit, das Legenden von Drachenjungen inspirierte. Die Predjama-Burg, in eine 123 Meter hohe Felswand gehauen, liegt nur 9 km entfernt.",highlights:["Unterirdische Bahn","Tropfsteine","Grottenolm","Predjama-Burg"],activities:["H\xf6hlentour mit Bahn","Predjama-Burg besuchen","Fotografie"],duration:"1 Tag"},piran:{tagline:"Sloweniens Venedig mit steinernen Gassen und dem Tartini-Platz",description:"Piran ist ein K\xfcstenst\xe4dtchen mit venezianischem Aussehen, in dem sich enge Gassen zwischen Steinh\xe4usern dr\xe4ngen. Der Tartini-Platz, der Hauptplatz mit Marmorbelag, ist dem Geiger Giuseppe Tartini gewidmet. Die Kirche St. Georg auf dem H\xfcgel blickt \xfcber die Adria.",highlights:["Tartini-Platz","Kirche St. Georg","K\xfcste","Alte Gassen"],activities:["Altstadtrundgang","Sonnenuntergang","Meeresk\xfcche","Salinen-Besuch"],duration:"1 Tag"},soca:{tagline:"Der smaragdgr\xfcne Fluss zwischen den Julischen Alpen f\xfcr Adrenalin-Abenteuer",description:"Die Soča ist einer der wenigen Fl\xfcsse, die ihre smaragdgr\xfcne Farbe das ganze Jahr beh\xe4lt. Sie schl\xe4ngelt sich durch Tolmin und Bovec und bietet erstklassiges Rafting, Kajak und Canyoning. Dazwischen liegen die Soča-Schluchten — Naturbecken im Kalkstein, perfekt zur Sommerabk\xfchlung.",highlights:["Soča-Schluchten","Bovec","Tolmin","Festung Kluže"],activities:["Rafting","Kajak","Canyoning","Zipline"],duration:"2–3 Tage"},triglav:{tagline:"2864 m hohes Nationalsymbol mit unz\xe4hligen Wegen",description:"Der Triglav ist Sloweniens h\xf6chster Gipfel und Nationalsymbol, er ziert das Staatswappen. Der Aufstieg erfordert technisches Wandern, ist bei guter Vorbereitung aber in ein bis zwei Tagen machbar. Auf dem Gipfel steht der Aljaž-Turm — die h\xf6chstgelegene Zuflucht des Landes.",highlights:["Gipfel 2864 m","Aljaž-Turm","Triglav-Rose","Wandern"],activities:["Wandern","Alpinismus","Fotografie"],duration:"2 Tage"},kobarid:{tagline:"Geschichte, Isonzofront und Kulinarik in einem Dorf",description:"Kobarid ist ein D\xf6rfchen an der Soča, bekannt f\xfcr das Kobarid-Museum, das die blutige Isonzofront des Ersten Weltkriegs dokumentiert. Die Napoleonbr\xfccke \xfcber die Soča und der Kolovrat bieten Panoramablicke. Hiša Franko, eines der besten Restaurants der Region, f\xfchrt die moderne Tolminer K\xfcche.",highlights:["Kobarid-Museum","Napoleonbr\xfccke","Kolovrat","Hiša Franko"],activities:["Museum","Wandern","Kulinarik-Erlebnis","Rad an der Soča"],duration:"1 Tag"},maribor:{tagline:"Die zweitgr\xf6\xdfte Stadt mit dem \xe4ltesten Weinstock der Welt",description:"Maribor liegt an der Drau, umgeben von den Weing\xe4rten des Pohorje. Der Alte Weinstock, \xfcber 400 Jahre alt, steht im Guinness-Buch der Rekorde. Die Stadt bietet einen lebendigen Altstadtkern, die Weingarten-Fluren des Pohorje und Winterskilauf.",highlights:["Alter Weinstock","Pohorje","Hauptplatz","Weinbau"],activities:["Besuch des Alten Weinstocks","Skifahren am Pohorje","Weinverkostung","Altstadt"],duration:"1–2 Tage"},portoroz:{tagline:"Das slowenische Seebad mit Casino und Wellness",description:"Portorož ist Sloweniens bekanntestes Seebad mit langem Sandstrand, Hotels mit Wellness-Centern und Casino. Die Uferpromenade verbindet Portorož mit Piran, die Salzfelder von Sečovlje bieten ein einzigartiges Naturerlebnis und Heilschlamm.",highlights:["Strand","Casino","Salzfelder Sečovlje","Wellness"],activities:["Schwimmen","Wellness","Gl\xfccksspiel","Rad am Meer"],duration:"2–3 Tage"},vintgar:{tagline:"Ein kurzer Spaziergang durch Kalkstein an einem stillen Fluss",description:"Die Vintgar-Klamm ist eine 1,6 km lange Schlucht an der Radovna, nur 4 km von Bled entfernt. Holzwege f\xfchren an kristallklarem Wasser vorbei, an einem Wasserfall und nat\xfcrlichen Becken. Der Spaziergang dauert etwa eine Stunde und eignet sich f\xfcr alle Altersgruppen.",highlights:["Wasserfall Šum","Holzwege","Kristallklars Wasser","Nat\xfcrliche Becken"],activities:["Spaziergang","Fotografie","Naturbeobachtung"],duration:"1 Tag"},rogaska:{tagline:"Das \xe4lteste slowenische Heilbad mit Mineralwasser",description:"Rogaška Slatina ist ein elegantes Kurort mit 400-j\xe4hriger Tradition, bekannt f\xfcr das Mineralwasser Donat Mg mit dem h\xf6chsten Magnesiumgehalt der Welt. Jugenststil-Architektur, Parks und Wellness-Center bieten ganzj\xe4hrige Entspannung.",highlights:["Donat Mg","Jugendstil-Architektur","Grand Hotel","Wellness"],activities:["Wellness","Mineralwasser-Trinken","Parkspazierg\xe4nge","Massagen"],duration:"2 Tage"},ptuj:{tagline:"Sloweniens \xe4lteste Stadt mit r\xf6mischer Geschichte",description:"Ptuj ist Sloweniens \xe4lteste dokumentierte Stadt, in der R\xf6merzeit als Poetovio gegr\xfcndet. Die mittelalterliche Burg auf dem H\xfcgel bietet Panoramablick auf die Drau, die Altstadt bewahrt Barockarchitektur. Bekannt f\xfcr das Kurentovanje — das gr\xf6\xdfte Karnevalsfest Mitteleuropas.",highlights:["Burg Ptuj","R\xf6mische Ausgrabungen","Kurentovanje","Drau"],activities:["Burgbesuch","Altstadtrundgang","Fasnachtsfestival","Spaziergang an der Drau"],duration:"1 Tag"},celje:{tagline:"Ehemalige Hauptstadt der Grafen von Celje mit beeindruckender Burg",description:"Celje ist Sloweniens drittgr\xf6\xdfte Stadt, bekannt f\xfcr die mittelalterliche Burg der Grafen von Celje — einst das einflussreichste Adelsgeschlecht der slowenischen L\xe4nder. Der Alte Markt bewahrt Barockfassaden, an der Savinja entlang zieht sich ein Spazierweg.",highlights:["Alte Burg Celje","Alter Markt","Savinja","Regionalmuseum"],activities:["Burgbesuch","Altstadtrundgang","Museum","Rad an der Savinja"],duration:"1 Tag"},"nova-gorica":{tagline:"Die Rosenstadt an der Grenze zu Italien",description:"Nova Gorica ist eine junge Stadt, gebaut nach dem Zweiten Weltkrieg, bekannt als „Stadt der Rosen“. Sie grenzt an das italienische Gorizia — die einzigen europ\xe4ischen St\xe4dte, die sich einen Platz teilen (Platz Europa). Casino, Parks und mediterranes Flair.",highlights:["Platz Europa","Rosengarten","Casino Perla","Br\xfccke von Solkan"],activities:["Parkspaziergang","Gl\xfccksspiel","Grenzspaziergang nach Italien","Rad an der Soča"],duration:"1 Tag"},"slovenj-gradec":{tagline:"Alpenst\xe4dtchen mit reicher Musikertradition",description:"Slovenj Gradec ist ein historisches St\xe4dtchen im Norden Sloweniens, umgeben von den K\xe4rntner Alpen. Bekannt f\xfcr die Halle slowenischer Musiker und als Geburtsstadt von Hugo Wolf. Ideale Ausgangspunkte f\xfcr Wanderungen auf Pohorje und Uršlja gora.",highlights:["Halle slowenischer Musiker","Alter Markt","Pohorje","Uršlja gora"],activities:["Wandern","Konzerte","Altstadtrundgang","Skifahren"],duration:"1 Tag"},dravograd:{tagline:"Dreifluss-Ecke von Drau, Meža und Mislinja",description:"Dravograd ist ein kleines St\xe4dtchen im Norden Sloweniens, wo sich drei Fl\xfcsse treffen — Drau, Meža und Mislinja. Umgeben von den W\xe4ldern des Kozjak und Pohorje. Wasserkraftwerk an der Drau und Wanderwege am Fluss.",highlights:["Zusammenfluss dreier Fl\xfcsse","Wasserkraftwerk Dravograd","Kozjak","Wandern"],activities:["Wandern","Angeln","Rad an der Drau","Naturfotografie"],duration:"1 Tag"},"murska-sobota":{tagline:"Zentrum der Prekmurje mit Schloss am See",description:"Murska Sobota ist das Zentrum der Prekmurje — der flachen pannonischen Landschaft im Nordosten Sloweniens. Das Schloss Murska Sobota am gleichnamigen See beherbergt das Regionalmuseum. Bekannt f\xfcr die Prekmurje-Gibanica und K\xfcrbis\xf6l.",highlights:["Schloss Murska Sobota","Sobota-See","Prekmurje-Gibanica","Regionalmuseum"],activities:["Schlossbesuch","Spaziergang am See","Kulinarik-Erlebnisse","Rad im Flachland"],duration:"1 Tag"},lendava:{tagline:"Zweisprachige Stadt mit Weing\xe4rten und Schloss auf dem H\xfcgel",description:"Lendava ist Sloweniens \xf6stlichste Stadt, an der Grenze zu Ungarn. Zweisprachige (slowenisch-ungarische) Stadt mit einem Schloss auf dem H\xfcgel, das Panoramablick auf die Weing\xe4rten der Lendava-H\xfcgel bietet. Anbau erstklassiger Wei\xdfweine.",highlights:["Schloss Lendava","Weing\xe4rten der Lendava-H\xfcgel","Zweisprachige Kultur","Weinkeller"],activities:["Weinverkostung","Schlossbesuch","Rad durch die Weing\xe4rten","Grenzspaziergang"],duration:"1 Tag"},"novo-mesto":{tagline:"Hauptstadt der Dolenjska an der Krka",description:"Novo mesto ist das Zentrum der Dolenjska, gebaut im Bogen des Flusses Krka. Der Alte Markt mit der Hauptstra\xdfe bewahrt mittelalterlichen Charakter. Bekannt f\xfcr den Cviček — den traditionellen Dolenjska-Wein — und arch\xe4ologische Funde der Hallstattkultur.",highlights:["Alter Markt","Fluss Krka","Cviček","Arch\xe4ologisches Museum"],activities:["Altstadtrundgang","Weinverkostung","Rad an der Krka","Museum"],duration:"1–2 Tage"},otocec:{tagline:"Sloweniens einzige Burg auf einer Flussinsel",description:"Otočec ist Sloweniens einzige Burg auf einer Insel, umgeben vom Fluss Krka. Heute ein Luxushotel mit Golfplatz und Wellness. Romantische Umgebung f\xfcr Paare und Ausgangspunkt f\xfcr Radtouren an der Krka.",highlights:["Burg auf der Insel","Fluss Krka","Golf","Wellness"],activities:["Golf","Wellness","Rad an der Krka","Romantisches Dinner"],duration:"1–2 Tage"},crnomelj:{tagline:"Das Herz der Bela krajina am Fluss Kolpa",description:"Črnomelj ist das Zentrum der Bela krajina — einer warmen, mediterran angehauchten Landschaft im S\xfcdosten Sloweniens am Fluss Kolpa. Bekannt f\xfcr die Bela-krajina-Pisanica (bemalte Eier), die Steljniki-Heiden und traditionelle Musik. Die Kolpa bietet das w\xe4rmste Badewasser Sloweniens.",highlights:["Fluss Kolpa","Alter Markt","Bela-krajina-Pisanica","Steljniki-Heiden"],activities:["Baden in der Kolpa","Altstadtrundgang","Rad durch die Bela krajina","Ethnografisches Museum"],duration:"1–2 Tage"},zagreb:{tagline:"Kroatiens Hauptstadt mit Wiener Charme und Kaffeekultur",description:"Zagreb ist eine Stadt an der Nahtstelle Mittel- und S\xfcdosteuropas mit einem Wien \xe4hnlichen Kern: die Oberstadt mit \xfcberdachtem Markt und dem Lotrščak-Turm, die Jugendstilstra\xdfen der Unterstadt und der lebendige Dolac am Morgen, wenn Bauern ihre Erzeugnisse aufbauen. Der Advent in der Oberstadt geh\xf6rt im Dezember zu den festlichsten Europas, im Sommer gibt der Kaffee in der Tkalčićeva-Stra\xdfe der Stadt den Takt.",highlights:["Oberstadt","Ban-Jelačić-Platz","Markt Dolac","Kathedrale"],activities:["Rundgang Oberstadt","Museen und Galerien","Advent im Dezember","Kaffee in der Tkalčićeva"],duration:"2 Tage"},"plitvicka-jezera":{tagline:"UNESCO-Kaskade t\xfcrkiser Seen und Wasserf\xe4lle",description:"Der \xe4lteste kroatische Nationalpark ist eine Kette von sechzehn Seen, die sich \xfcber Travertind\xe4mme und Wasserf\xe4lle ineinander ergie\xdfen. Holzstiege f\xfchren am Wasser durch den Wald, \xfcber den gr\xf6\xdften See Kozjak fahren elektrische Boote. Die Wasserfarbe wandert je nach Jahreszeit und Licht zwischen T\xfcrkis und Smaragd.",highlights:["Gro\xdfer Wasserfall","See Kozjak","Holzstiegen","Travertind\xe4mme"],activities:["Stiegenrundgang","Bootsfahrt auf dem Kozjak","Fotografie","Gro\xdfer Wasserfall"],duration:"1 Tag"},rijeka:{tagline:"Kulturhauptstadt mit Kroatiens gr\xf6\xdftem Hafen",description:"Rijeka ist eine Hafenstadt an der Kvarner-Bucht mit \xf6sterreichisch-ungarischem Kern, dem langen Korzo und der Trsat-Burg auf dem H\xfcgel \xfcber der Stadt. 2020 war sie europ\xe4ische Kulturhauptstadt; der Oster-Karneval von Rijeka geh\xf6rt zu den gr\xf6\xdften Europas. Von Rijeka f\xfchren F\xe4hren zu den Inseln und nach Italien — die Stadt ist das Tor zum Kvarner.",highlights:["Korzo","Burg Trsat","Stadtturm","Kathedrale St. Vid"],activities:["Korzo-Spaziergang","Blick vom Trsat","Karneval von Rijeka","F\xe4hrenausfl\xfcge zu den Inseln"],duration:"1–2 Tage"},pula:{tagline:"R\xf6misches Amphitheater an der Adria",description:"Pula ist Istriens gr\xf6\xdfte Stadt mit dem am besten erhaltenen r\xf6mischen Amphitheater der Welt nach Rom — die Arena aus dem 1. Jahrhundert beherbergt bis heute Konzerte und Open-Air-Kino. Die Altstadt mit Goldenem Tor und der Kathedrale Santa Maria dr\xe4ngt sich auf der Halbinsel, um die Stadt liegen Str\xe4nde und istrische Winzerd\xf6rfer.",highlights:["Amphitheater Arena","Goldenes Tor","Alter Platz","Istrische Riviera"],activities:["Arena-Besuch","Altstadtrundgang","Baden","Weinverkostungen in Istrien"],duration:"1–2 Tage"},zadar:{tagline:"Stadt des Sonnenuntergangs und der Meeresorgel",description:"Zadar ist eine dalmatinische Stadt auf einer Halbinsel mit r\xf6mischem Grundriss und der romanischen Kirche St. Donat. An der K\xfcste spielt die Meeresorgel mit den Wellen, daneben der Gru\xdf an die Sonne — eine Installation, bei der sich zur Sonnenuntergangsstunde Mengen sammeln; Alfred Hitchcock nannte Zadars Untergang den sch\xf6nsten der Welt. Von Zadar sind es die k\xfcrzesten Ausfl\xfcge zu den Kornaten.",highlights:["Meeresorgel","Gru\xdf an die Sonne","Kirche St. Donat","R\xf6mische Ruinen"],activities:["Meeresorgel h\xf6ren","Sonnenuntergang","Rundgang auf den Mauern","Ausflug zu den Kornaten"],duration:"1–2 Tage"},split:{tagline:"Lebendige Stadt im Inneren des Diokletianpalasts",description:"Das Herz von Split ist der Diokletianpalast aus dem 4. Jahrhundert — ein r\xf6misches Komplex, in dem heute Menschen leben: Caf\xe9s im Peristyl, M\xe4rkte in den Katakomben, Boutiquen in den Gew\xf6lben. Die Kathedrale des Hl. Domnius ist die \xe4lteste ununterbrochen genutzte Kathedrale der Welt. Der H\xfcgel Marjan bietet die Flucht in die Kiefern \xfcber der Stadt, vom Hafen legen F\xe4hren zu den Inseln ab.",highlights:["Diokletianpalast","Peristyl","Kathedrale des Hl. Domnius","Marjan"],activities:["Palast erkunden","Spaziergang auf den Marjan","Strand Bačvice","F\xe4hren zu den Inseln"],duration:"2 Tage"},hvar:{tagline:"Die sonnigste Adria-Insel aus Lavendel und Stein",description:"Hvar ist eine Insel mit fast 2800 Sonnenstunden im Jahr, einer venezianisch anmutenden Hafenstadt und der Festung Fortica auf dem H\xfcgel. Das Inselinnere verbirgt Lavendelfelder und Weing\xe4rten der bogotinjava pošipina (Rebsorte). Vor dem Hafen liegen die Pakleni-Inseln — Schieferbuchten zum Ankern und Baden.",highlights:["Festung Fortica","Hafen von Hvar","Pakleni-Inseln","Lavendelfelder"],activities:["Blick von der Fortica","Ausflug zu den Pakleni-Inseln","Pošip-Verkostung","Baden in Buchten"],duration:"2–3 Tage"},dubrovnik:{tagline:"Mittelalterliche Mauerstadt \xfcber dem blauen Adria",description:"Dubrovnik — die Republik, die jahrhundertelang mit Venedig wetteiferte — ist eine Mauerstadt an der Klippe \xfcber dem Meer, deren Stradun die Tore Pile und Ploče verbindet. Die fast zwei Kilometer langen Mauern bieten den ber\xfchmtesten Stadtrundgang der Adria; die Seilbahn hinauf zum Srđ bietet Blick auf Altstadt und Inseln. Vor der Stadt liegt die bewaldete Insel Lokrum.",highlights:["Stadtmauern","Stradun","Insel Lokrum","Seilbahn auf den Srđ"],activities:["Rundgang auf den Mauern","Franziskanerkreuzgang","Ausflug nach Lokrum","Sonnenuntergang vom Srđ"],duration:"2–3 Tage"},kotor:{tagline:"Eine fjord\xe4hnliche Bucht mit mittelalterlicher Mauerstadt",description:"Kotor liegt am Grund der Bucht von Kotor, die sich zwischen steilen Bergen wie der einzige Fjord des Mittelmeers windet. Die Altstadt mit ihrem Netz aus Pl\xe4tzen und Gassen steht unter UNESCO-Schutz; die Mauern mit der Festung San Giovanni steigen \xfcber 1200 Stufen \xfcber die Stadt und bieten legend\xe4ren Blick auf die Bucht. Im benachbarten Perast liegt die Barockinsel Gospa od Škrpjela.",highlights:["Altstadt Kotor","Mauern von San Giovanni","Bucht von Kotor","Perasto"],activities:["Altstadtrundgang","Aufstieg auf die Mauern","Ausflug nach Perasto","Kreuzfahrt durch die Bucht"],duration:"1–2 Tage"},budva:{tagline:"Altstadt auf einer Halbinsel zwischen Str\xe4nden und Kiefern",description:"Budva ist Montenegros meistbesuchter Badeort — Altstadt auf einer felsigen Halbinsel mit Mauern, darum herum eine Kette von Str\xe4nden (Mogren, Jaz, Slowenischer Strand). Im Sommer sind Stra\xdfen und Terrassen voll, im Herbst und Fr\xfchjahr atmet die Altstadt entspannt. Das bekannteste Fotomotiv ist das Inselchen Sveti Stefan mit dem ehemaligen Dorf-Hotel.",highlights:["Altstadt Budva","Strand Mogren","Sveti Stefan","Strand Jaz"],activities:["Altstadtrundgang","Baden am Mogren","Blick auf Sveti Stefan","Abende an der K\xfcste"],duration:"1–2 Tage"},podgorica:{tagline:"Entspannte Hauptstadt am Schnittpunkt von Fl\xfcssen und Bergen",description:"Podgorica ist Montenegros Hauptstadt und gr\xf6\xdfte Stadt, erbaut am Zusammenfluss von Morača und Ribnica. Den Rhythmus geben Korzo, Kaffeeterrassen und die Millenniumsbr\xfccke; die Stara Varoš bewahrt osmanische Reste mit dem Uhrturm. Ausgegangspunkt — der Skutarisee, Budva und Durmitor sind Tagesausfl\xfcge.",highlights:["Millenniumsbr\xfccke","Stara Varoš","Uhrturm","Gorica"],activities:["Korzo-Spaziergang","Stara Varoš erkunden","Kaffee an der Morača","Ausflug zum Skutarisee"],duration:"1 Tag"},durmitor:{tagline:"UNESCO-Gebirge \xfcber dem Schwarzen See und der Tara-Schlucht",description:"Der Nationalpark Durmitor ist ein von 18 Gletscherseen durchsetztes Gebirge — bekanntestes ist der Schwarze See bei Žabljak, der Bergstadt. Die Schlucht der Tara ist die tiefste Europas (1300 m) und Heimat des Raftings zwischen den Ufern; die Panoramastra\xdfe \xfcber das Sedlo Soa verbindet Žabljak mit dem S\xfcden. Im Winter Skigebiete, im Sommer Wanderwege um die Seen.",highlights:["Schwarzer See","Tara-Schlucht","Žabljak","Sedlo Soa"],activities:["Wanderung um den Schwarzen See","Rafting auf der Tara","Panoramafahrt \xfcber das Sedlo","Winterskilauf"],duration:"2–3 Tage"},tirana:{tagline:"Bunte Hauptstadt mit osmanischem Kern und Kaffeetempo",description:"Tirana ist eine Hauptstadt, die sich nach langen Jahrzehnten ge\xf6ffnet hat — farbige Fassaden, der Skanderbeg-Platz mit der Et'hem-Bej-Moschee und dem Uhrturm, Caf\xe9s in den Blockstra\xdfen. Die Dajti-Ekspres-Seilbahn steigt auf 1600 m \xfcber der Stadt f\xfcr den Blick \xfcber Ebene und Adria; das Museum Bunk'Art in einem Atombunker erz\xe4hlt das 20. Jahrhundert.",highlights:["Skanderbeg-Platz","Et'hem-Bej-Moschee","Bunk'Art","Berg Dajti"],activities:["Zentrum erkunden","Seilbahn auf den Dajti","Museen","Kaffeekultur"],duration:"2 Tage"},berat:{tagline:"Die Stadt der tausend Fenster unter der Burg an der Osum",description:"Berat ist eine UNESCO-gesch\xfctzte Stadt, bekannt als Stadt der tausend Fenster — die wei\xdfen osmanischen H\xe4user des Viertels Mangalem steigen treppenartig zur Burg auf der Spitze hinauf. Die alte Br\xfccke \xfcber den Fluss Osum verbindet das Viertel Gorica; in der Burg liegt das Onufri-Museum mit Ikonen. Um Berat herum liegen Weing\xe4rten, mit Verkostungen in traditionellen H\xe4usern.",highlights:["Burg von Berat","Viertel Mangalem","Alte Br\xfccke","Onufri-Museum"],activities:["Rundgang im Mangalem","Burgbesuch","Br\xfccke \xfcber die Osum","Weinverkostung"],duration:"1 Tag"},gjirokaster:{tagline:"Die Stadt aus Stein — graue D\xe4cher unter einer gewaltigen Burg",description:"Gjirokast\xebr ist eine UNESCO-Stadt aus Steinh\xe4usern mit Schindeld\xe4chern, erbaut an einem steilen Hang unter einer der gr\xf6\xdften Burgen des Balkans. Der alte Basar bewahrt die osmanische Handelstra\xdfe mit ihren Bogeng\xe4ngen; das Geburtshaus des Schriftstellers Ismail Kadare ist heute Museum. \xdcber dem Tal schwebt die Legende von Zerm und den Najaden — die Berge rundum laden zum Wandern ein.",highlights:["Burg von Gjirokast\xebr","Alter Basar","Steinh\xe4user","Kadare-Haus"],activities:["Burgbesuch","Basar-Rundgang","Ethnografisches Museum","Wanderungen in der Umgebung"],duration:"1 Tag"},saranda:{tagline:"Sonnige Ionische Stadt gegen\xfcber Korfu",description:"Saranda ist Albaniens s\xfcdlichste Badestadt, gegen\xfcber dem griechischen Korfu (F\xe4hre 30 Min). Die K\xfcste s\xfcdlich der Stadt verbirgt Ksamil mit wei\xdfen Str\xe4nden und Inselchen, das Landesinnere die Antike — Butrint ist eine UNESCO-Antikenstadt zwischen See und Kanal. Der Blick von der Festung L\xebkur\xebsi \xfcber der Stadt schenkt am Abend den Sonnenuntergang \xfcber dem Ionischen Meer.",highlights:["Ksamil","Antikes Butrint","Festung L\xebkur\xebsi","Blick auf Korfu"],activities:["Baden in Ksamil","Butrint besuchen","Sonnenuntergang von L\xebkur\xebsi","F\xe4hre nach Korfu"],duration:"2–3 Tage"}};function r(e){return n[e]??null}},53670:(e,a,i)=>{i.d(a,{J:()=>r});let n={bled:{tagline:"La perla de los Alpes con un castillo medieval y una isla",description:"El lago de Bled, con su \xfanica isla coronada por una iglesia y un campanario, es el paisaje m\xe1s ic\xf3nico de Eslovenia. El castillo medieval, emplazado en un acantilado, ofrece vistas panor\xe1micas, mientras que el desfiladero de Vintgar invita a un paseo breve a trav\xe9s de piedra caliza junto a un tranquilo r\xedo. Una porci\xf3n de tarta de nata de Bled (kremšnita) en una pasteler\xeda junto al lago es el dulce obligatorio.",highlights:["Isla de Bled","Castillo de Bled","Desfiladero de Vintgar","Tarta de nata de Bled (kremšnita)"],activities:["Traves\xeda en barca pletna hasta la isla","Visita al castillo","Paseo por el desfiladero","Nadar"],duration:"1-2 d\xedas"},bohinj:{tagline:"Una salvaje y virgen belleza del Parque Nacional Triglav",description:"El lago de Bohinj es el hermano mayor y m\xe1s salvaje del lago de Bled, ubicado en su totalidad dentro del Parque Nacional Triglav. El telef\xe9rico Vogel ofrece vistas panor\xe1micas de los Alpes Julios, y la cascada Savica es una corta ruta senderista a trav\xe9s del bosque. Ideal para quienes buscan tranquilidad y una escapada activa a la naturaleza.",highlights:["Lago de Bohinj","Vogel","Cascada Savica","Parque Nacional Triglav"],activities:["Senderismo","Esqu\xed","Kayak","Telef\xe9rico Vogel"],duration:"1-2 d\xedas"},ljubljana:{tagline:"Una capital verde y creativa con el Puente del Drag\xf3n",description:"Liubliana es una peque\xf1a pero animada capital donde la arquitectura medieval se fusiona con la escena culinaria contempor\xe1nea. El castillo de Liubliana ofrece vistas panor\xe1micas, la plaza de Prešeren con el Puente del Drag\xf3n es el coraz\xf3n de la ciudad, y las orillas del r\xedo Liubljanica cobran vida con el caf\xe9 y la conversaci\xf3n.",highlights:["Castillo de Liubliana","Puente del Drag\xf3n","Plaza de Prešeren","Parque de Tivoli"],activities:["Visita al castillo","Paseo por el casco antiguo","Tour gastron\xf3mico","Ruta en bicicleta por el Liubljanica"],duration:"2 d\xedas"},postojna:{tagline:"24 km de pasajes subterr\xe1neos y un reino de hadas de estalactitas",description:"La cueva de Postojna es el mayor sistema de cuevas tur\xedsticas de Europa, con un tren subterr\xe1neo \xfanico. Tambi\xe9n es el hogar de la proteus, un endemismo que inspir\xf3 leyendas sobre cr\xedas de drag\xf3n. El castillo de Predjama, tallado en una pared de acantilado de 123 metros, se encuentra a solo 9 km de distancia.",highlights:["Tren subterr\xe1neo","Estalactitas","Proteus (pez humano)","Castillo de Predjama"],activities:["Tour de cuevas en tren","Visita al castillo de Predjama","Fotograf\xeda"],duration:"1 d\xeda"},piran:{tagline:"La Venecia eslovena con callejones de piedra y la Plaza Tartini",description:"Piran es un pueblo costero de estilo veneciano, donde las callejuelas estrechas se estrechan entre casas de piedra. La Plaza Tartini, la plaza principal con pavimento de m\xe1rmol, est\xe1 dedicada al violinista Giuseppe Tartini. La Iglesia de San Jorge en la colina ofrece vistas al Mar Adri\xe1tico.",highlights:["Plaza Tartini","Iglesia de San Jorge","La costa","Callejuelas antiguas"],activities:["Paseo por el casco antiguo","Ver el atardecer","Degustaci\xf3n de marisco","Visita a las salinas"],duration:"1 d\xeda"},soca:{tagline:"Un r\xedo esmeralda entre los Alpes Julianos para aventuras con adrenalina",description:"La Soča es uno de los pocos r\xedos que mantiene su color esmeralda durante todo el a\xf1o. Serpentea por Tolmin y Bovec, donde ofrece rafting de primer nivel, kayak y descenso de ca\xf1ones. A lo largo de su curso se encuentran las gargantas de la Soča — piscinas naturales talladas en la caliza, perfectas para refrescarse en verano.",highlights:["Gargantas de la Soča","Bovec","Tolmin","Fortaleza de Kluže"],activities:["Rafting","Kayak","Descenso de ca\xf1ones","Zip-line"],duration:"2-3 d\xedas"},triglav:{tagline:"S\xedmbolo nacional de 2.864 m con innumerables senderos",description:"El Triglav es el pico m\xe1s alto de Eslovenia y un s\xedmbolo nacional que incluso aparece en el escudo del pa\xeds. La ascensi\xf3n requiere senderismo t\xe9cnico, pero con una buena preparaci\xf3n es alcanzable en uno o dos d\xedas. En la cumbre se alza la torre de Aljaž — el refugio m\xe1s alto del pa\xeds.",highlights:["Cumbre de 2.864 m","Torre de Aljaž","Rosa del Triglav","Senderismo"],activities:["Senderismo","Alpinismo","Fotograf\xeda"],duration:"2 d\xedas"},kobarid:{tagline:"Historia, el Frente del Isonzo y gastronom\xeda en un mismo pueblo",description:"Kobarid es un peque\xf1o pueblo junto al r\xedo Soča, famoso por el Museo de Kobarid, que documenta la sangrienta batalla del Frente del Isonzo durante la Primera Guerra Mundial. El puente de Napole\xf3n sobre el r\xedo Soča y la cresta de Kolovrat ofrecen vistas panor\xe1micas. Hiša Franko, uno de los mejores restaurantes de la regi\xf3n, sirve la cocina contempor\xe1nea de Tolmin.",highlights:["Museo de Kobarid","Puente de Napole\xf3n","Kolovrat","Hiša Franko"],activities:["Visita al museo","Senderismo","Experiencia gastron\xf3mica","Rutas en bicleta junto al Soča"],duration:"1 d\xeda"},maribor:{tagline:"La segunda ciudad de Eslovenia, hogar de la vid m\xe1s antigua del mundo",description:"Maribor se encuentra en el r\xedo Drava, rodeada de vi\xf1edos de Pohorje. La Vieja Vides, con m\xe1s de 400 a\xf1os de antig\xfcedad, est\xe1 inscrita en el Libro Guinness de los R\xe9cords. La ciudad ofrece un animado casco antiguo, las laderas vin\xedcolas de Pohorje y esqu\xed en invierno.",highlights:["La Vieja Vides","Pohorje","Plaza Principal","Cultura del vino"],activities:["Visita a la Vieja Vides","Esqu\xed en Pohorje","Degustaci\xf3n de vinos","Paseo por el casco antiguo"],duration:"1-2 d\xedas"},portoroz:{tagline:"Estaci\xf3n balnearia eslovena con casino y bienestar",description:"Portorož es la estaci\xf3n balnearia m\xe1s famosa de Eslovenia, con una larga playa de arena, hoteles con centros de bienestar y un casino. El paseo mar\xedtimo conecta Portorož con Piran, mientras que las salinas de Sečovlje ofrecen una experiencia natural \xfanica y tratamientos de bienestar con lodo.",highlights:["Playa","Casino","Salinas de Sečovlje","Bienestar"],activities:["Nataci\xf3n","Bienestar","Juegos de azar","Ciclismo junto al mar"],duration:"2-3 d\xedas"},vintgar:{tagline:"Un corto paseo por un ca\xf1\xf3n de piedra caliza junto a un tranquilo r\xedo",description:"El desfiladero de Vintgar es un ca\xf1\xf3n de 1,6 km de longitud a orillas del r\xedo Radovna, a solo 4 km de Bled. Pasarelas de madera serpentan junto a aguas cristalinas, pasando por una cascada y piscinas naturales. El paseo dura aproximadamente una hora y es apto para todas las edades.",highlights:["Cascada de Šum","Pasarelas de madera","Agua cristalina","Piscinas naturales"],activities:["Pasear","Fotograf\xeda","Observaci\xf3n de la naturaleza"],duration:"1 d\xeda"},rogaska:{tagline:"El balneario m\xe1s antiguo de Eslovenia con agua mineral",description:"Rogaška Slatina es un elegante balneario con una tradici\xf3n de 400 a\xf1os, famoso por su agua mineral Donat Mg, con el contenido m\xe1s alto de magnesio del mundo. La arquitectura modernista, los parques y los centros de bienestar ofrecen relajaci\xf3n durante todo el a\xf1o.",highlights:["Donat Mg","Arquitectura modernista","Gran Hotel","Bienestar"],activities:["Bienestar","Degustaci\xf3n de agua mineral","Paseos por el parque","Masajes"],duration:"2 d\xedas"},ptuj:{tagline:"La ciudad m\xe1s antigua de Eslovenia con historia romana",description:"Ptuj es la ciudad m\xe1s antigua registrada de Eslovenia, fundada en la \xe9poca romana como Poetovio. El castillo medieval en la colina ofrece vistas panor\xe1micas sobre el r\xedo Drava, mientras el casco antiguo conserva su arquitectura barroca. Es famosa por el Kurentovanje, el mayor festival de carnaval de Europa Central.",highlights:["Castillo de Ptuj","Restos romanos","Kurentovanje","R\xedo Drava"],activities:["Visita al castillo","Paseo por el casco antiguo","Festival de carnaval","Paseo por la orilla del r\xedo Drava"],duration:"1 d\xeda"},celje:{tagline:"Antigua capital de los condes de Celje con un impresionante castillo",description:"Celje es la tercera ciudad m\xe1s grande de Eslovenia, conocida por su castillo medieval de los Condes de Celje, anta\xf1o la dinast\xeda noble m\xe1s influyente de las tierras eslovenas. La Plaza Vieja conserva sus fachadas barrocas, y un paseo serpentea a lo largo del r\xedo Savinja.",highlights:["Castillo Viejo de Celje","Plaza Vieja","R\xedo Savinja","Museo Regional"],activities:["Visita al castillo","Paseo por el casco antiguo","Visita al museo","Ruta en bicleta por el r\xedo Savinja"],duration:"1 d\xeda"},"nova-gorica":{tagline:"La ciudad de las rosas en la frontera con Italia",description:"Nova Gorica es una ciudad joven construida despu\xe9s de la Segunda Guerra Mundial, conocida como la 'ciudad de las rosas'. Limita con la ciudad italiana de Gorizia — las \xfanicas dos ciudades europeas que comparten una misma plaza (Plaza de Europa). Un casino, parques frondosos y una atm\xf3sfera mediterr\xe1nea completan el escenario.",highlights:["Plaza de Europa","Parque de las Rosas","Casino Perla","Puente de Solkan"],activities:["Paseo por el parque","Juegos de azar","Paseo fronterizo a Italia","Ciclismo por el Soča"],duration:"1 d\xeda"},"slovenj-gradec":{tagline:"Un pueblo alpino con rica tradici\xf3n musical",description:"Slovenj Gradec es un hist\xf3rico pueblo del norte de Eslovenia, rodeado por los Alpes Carintios. Conocido por la Sala de los M\xfasicos Eslovenos y por ser el lugar de nacimiento del compositor Hugo Wolf. Es el punto de partida ideal para excursiones a pie por Pohorje y Uršlja Gora.",highlights:["Sala de los M\xfasicos Eslovenos","Plaza Vieja","Pohorje","Uršlja Gora"],activities:["Senderismo","Conciertos de m\xfasica","Paseo por el casco antiguo","Esqu\xed"],duration:"1 d\xeda"},dravograd:{tagline:"Donde confluyen los r\xedos Drava, Meža y Mislinja",description:"Dravograd es un peque\xf1o pueblo del norte de Eslovenia donde se encuentran tres r\xedos: el Drava, el Meža y el Mislinja. Est\xe1 rodeado por los bosques de Kozjak y Pohorje. Entre sus puntos de inter\xe9s destacan la central hidroel\xe9ctrica del Drava y los senderos de senderismo a orillas del r\xedo.",highlights:["Confluencia de tres r\xedos","Central hidroel\xe9ctrica de Dravograd","Kozjak","Senderismo"],activities:["Senderismo","Pesca","Cicloturismo por el Drava","Fotograf\xeda de naturaleza"],duration:"1 d\xeda"},"murska-sobota":{tagline:"El coraz\xf3n de Prekmurje con un castillo junto al lago",description:"Murska Sobota es el centro de Prekmurje, la llana regi\xf3n pan\xf3nica del noreste de Eslovenia. El Castillo de Murska Sobota, junto al lago del mismo nombre, alberga el Museo Regional. Conocida por la gibanica prekmurja, una pasta tradicional capas, y el aceite de semilla de calabaza.",highlights:["Castillo de Murska Sobota","Lago de Sobota","Gibanica prekmurja","Museo Regional"],activities:["Visita al castillo","Paseo junto al lago","Experiencias culinarias","Rutas en bicicleta por la llanura"],duration:"1 d\xeda"},lendava:{tagline:"Ciudad biling\xfce con vi\xf1edos y un castillo en la colina",description:"Lendava es la ciudad m\xe1s oriental de Eslovenia, situada en la frontera con Hungr\xeda. Esta ciudad biling\xfce (esloveno-h\xfangara) alberga un castillo en la colina que ofrece vistas panor\xe1micas a los vi\xf1edos de las colinas de Lendavske gorice. La zona produce vinos blancos de alta gama.",highlights:["Castillo de Lendava","Vi\xf1edos de las colinas de Lendavske gorice","Cultura biling\xfce","Bodega de vinos"],activities:["Degustaci\xf3n de vinos","Visita al castillo","Ruta en bicicleta por los vi\xf1edos","Paseo transfronterizo"],duration:"1 d\xeda"},"novo-mesto":{tagline:"La capital de Dolenjska en el r\xedo Krka",description:"Novo mesto es el centro de la regi\xf3n de Dolenjska, construido en un meandro del r\xedo Krka. La Plaza Vieja y su calle principal conservan su car\xe1cter medieval. La ciudad es famosa por el cviček — el vino tradicional de Dolenjska — y por los hallazgos arqueol\xf3gicos de la cultura de Hallstatt.",highlights:["Plaza Vieja","R\xedo Krka","Cviček","Museo Arqueol\xf3gico"],activities:["Paseo por el casco antiguo","Degustaci\xf3n de vinos","Ruta en bicicleta por el Krka","Visita al museo"],duration:"1-2 d\xedas"},otocec:{tagline:"El \xfanico castillo esloveno en una isla fluvial",description:"Otočec es el \xfanico castillo de Eslovenia situado en una isla, rodeado por las aguas del r\xedo Krka. En la actualidad, es un hotel de lujo con campo de golf y instalaciones de bienestar. Un entorno rom\xe1ntico para parejas y punto de partida para el ciclismo a lo largo del Krka.",highlights:["Castillo en la isla","R\xedo Krka","Golf","Bienestar"],activities:["Golf","Bienestar","Ruta en bicicleta por el Krka","Cena rom\xe1ntica"],duration:"1-2 d\xedas"},crnomelj:{tagline:"El coraz\xf3n de la regi\xf3n de Bela Krajina en el r\xedo Kolpa",description:"Crnomelj es el centro de Bela Krajina, una c\xe1lida regi\xf3n de influencia mediterr\xe1nea en el sureste de Eslovenia, situada en el r\xedo Kolpa. Conocida por sus huevos de Pascua pintados (pisanica), sus brezales y su m\xfasica tradicional de Bela Krajina. El r\xedo Kolpa ofrece las aguas m\xe1s c\xe1lidas para nadar de Eslovenia.",highlights:["R\xedo Kolpa","Plaza Vieja","Pisanica de Bela Krajina","Brezales"],activities:["Ba\xf1o en el r\xedo Kolpa","Paseo por el casco antiguo","Ruta ciclista por Bela Krajina","Museo etnogr\xe1fico"],duration:"1-2 d\xedas"},zagreb:{tagline:"La capital croata con el encanto vien\xe9s y la cultura del caf\xe9",description:"Zagreb es una ciudad en la encrucijada de Europa Central y del Sudeste, con un n\xfacleo de \xe9poca austroh\xfangara: la ciudad alta con su mercado cubierto y la torre Lotrščak, las calles modernistas de la ciudad baja y el animado mercado Dolac por la ma\xf1ana cuando los agricultores exponen sus productos. Su feria de Adviento es una de las m\xe1s festivas de Europa en diciembre, mientras que el caf\xe9 de verano en la calle Tkalčićeva marca el ritmo de la ciudad.",highlights:["Ciudad Alta","Plaza de Ban Jelačić","Mercado Dolac","Catedral"],activities:["Paseo por la Ciudad Alta","Museos y galer\xedas","Adviento en diciembre","Caf\xe9 en la calle Tkalčićeva"],duration:"2 d\xedas"},"plitvicka-jezera":{tagline:"Una cascada de lagos y cascadas turquesas del Patrimonio Mundial de la UNESCO",description:"El parque nacional m\xe1s antiguo de Croacia es una cadena de diecis\xe9is lagos que se derraman unos en otros sobre barreras de travertino y cascadas. Pasarelas de madera recorren el agua a trav\xe9s del bosque, y barcas el\xe9ctricas cruzan el lago m\xe1s grande, Kozjak. El color del agua var\xeda entre el turquesa y el esmeralda seg\xfan la estaci\xf3n y la luz.",highlights:["Gran Salto","Lago Kozjak","Pasarelas de madera","Barreras de travertino"],activities:["Paseo por las pasarelas","Traves\xeda en barco por Kozjak","Fotograf\xeda","Visita al Gran Salto"],duration:"1 d\xeda"},rijeka:{tagline:"Capital de cultura con el mayor puerto de Croacia",description:"Rijeka es una ciudad portuaria en el golfo de Kvarner, con un n\xfacleo austroh\xfangaro, el largo paseo de Korzo y el castillo de Trsat en la colina sobre la ciudad. Fue Capital Europea de Cultura en 2020; su carnaval de Pascua es uno de los m\xe1s grandes de Europa. Desde Rijeka parten ferries hacia las islas e Italia — la ciudad es la puerta de entrada al Kvarner.",highlights:["Korzo","Castillo de Trsat","Torre de la ciudad","Catedral de San Vito"],activities:["Paseo por Korzo","Vista desde Trsat","Carnaval de Rijeka","Excursiones en ferry a las islas"],duration:"1-2 d\xedas"},pula:{tagline:"Anfiteatro romano en el Adri\xe1tico",description:"Pula es la ciudad m\xe1s grande de Istria, hogar del anfiteatro romano mejor conservado del mundo despu\xe9s de Roma — el anfiteatro del siglo I sigue acogiendo conciertos y cine al aire libre. El casco antiguo con la Puerta Dorada y la Catedral de Santa Mar\xeda se extiende en una pen\xednsula, rodeado de playas y pueblos vin\xedcolas de Istria.",highlights:["Anfiteatro Arena","Puerta Dorada","Plaza del Viejo Mercado","Riviera de Istria"],activities:["Visita al Anfiteatro Arena","Paseo por el casco antiguo","Nataci\xf3n","Degustaciones de vinos de Istria"],duration:"1-2 d\xedas"},zadar:{tagline:"La ciudad de las puestas de sol y los \xf3rganos del mar",description:"Zadar es una ciudad d\xe1lmata en una pen\xednsula con un plano romano y la iglesia rom\xe1nica de San Donato. En el paseo mar\xedtimo, los \xf3rganos del mar tocan con las olas, junto al Saludo al Sol — una instalaci\xf3n donde se re\xfanen multitudes al atardecer; Alfred Hitchcock calific\xf3 el atardecer de Zadar como el m\xe1s bello del mundo. Desde Zadar, las excursiones a las islas Kornati son las m\xe1s cortas.",highlights:["\xd3rganos del mar","Saludo al Sol","Iglesia de San Donato","Ruinas romanas"],activities:["Escuchar los \xf3rganos del mar","Ver el atardecer","Paseo por las murallas","Excursi\xf3n a las Kornati"],duration:"1-2 d\xedas"},split:{tagline:"Una ciudad viva dentro del Palacio de Diocleciano",description:"El coraz\xf3n de Split es el Palacio de Diocleciano del siglo IV — un complejo romano donde la gente sigue viviendo: caf\xe9s en el Peristilo, un mercado en los s\xf3tanos y tiendas en las salas abovedadas. La Catedral de San Domnius es la catedral m\xe1s antigua del mundo en uso continuo. La colina de Marjan ofrece un escape en pinos sobre la ciudad, y desde el puerto zarpan los ferries hacia las islas.",highlights:["Palacio de Diocleciano","Peristilo","Catedral de San Domnius","Marjan"],activities:["Explorar el palacio","Paseo por Marjan","Playa de Bačvice","Trayectos en ferry a las islas"],duration:"2 d\xedas"},hvar:{tagline:"La isla m\xe1s soleada del Adri\xe1tico de lavanda y vino",description:"Hvar tiene casi 2.800 horas de sol al a\xf1o, un puerto de aspecto veneciano y la fortaleza Fortica en la colina. El interior de la isla esconde campos de lavanda y vi\xf1edos de la variedad de vino pošip. Frente al puerto se encuentran las islas Pakleni — calas rocosas para fondear y ba\xf1arse.",highlights:["Fortaleza Fortica","Puerto de Hvar","Islas Pakleni","Campos de lavanda"],activities:["Vista desde Fortica","Excursi\xf3n a las islas Pakleni","Degustaci\xf3n de vino pošip","Ba\xf1o en las calas"],duration:"2-3 d\xedas"},dubrovnik:{tagline:"Ciudad medieval amurallada sobre el Adri\xe1tico azul",description:"Dubrovnik — la Rep\xfablica de Ragusa que compiti\xf3 con Venecia durante siglos — es una ciudad amurallada que se alza sobre el mar, cuyo Stradun une las puertas de Pile y Ploče. El paseo por la muralla, de casi dos kil\xf3metros, es el m\xe1s famoso del Adri\xe1tico; un telef\xe9rico sube a Srđ para contemplar la vista de la ciudad antigua y las islas. Frente a la ciudad se encuentra la isla boscosa de Lokrum.",highlights:["Murallas de la ciudad","Stradun","Isla de Lokrum","Telef\xe9rico a Srđ"],activities:["Paseo por las murallas","Claustro del monasterio franciscano","Excursi\xf3n a Lokrum","Atardecer desde Srđ"],duration:"2-3 d\xedas"},kotor:{tagline:"Una bah\xeda similar a un fiordo con una ciudad amurallada medieval",description:"Kotor se encuentra en el fondo de la bah\xeda de Kotor, que serpentea entre monta\xf1as escarpadas como el \xfanico fiordo del Mediterr\xe1neo. El casco antiguo, protegido por la UNESCO, es una red de plazas y callejuelas; las murallas del castillo de San Giovanni suben m\xe1s de 1.200 escalones sobre la ciudad para ofrecer una legendaria vista de la bah\xeda. En la cercana Perast se encuentra la isla barroca de Nuestra Se\xf1ora de las Roca.",highlights:["Casco antiguo de Kotor","Murallas de San Giovanni","Bah\xeda de Kotor","Perast"],activities:["Paseo por el casco antiguo","Ascenso a las murallas","Excursi\xf3n a Perast","Crucero por la bah\xeda"],duration:"1-2 d\xedas"},budva:{tagline:"Una ciudad antigua en una pen\xednsula entre playas y pinos",description:"Budva es el destino costero m\xe1s visitado de Montenegro: su casco antiguo se encuentra en un promontorio rocoso y amurallado, rodeado de playas (Mogren, Jaz, Playa Eslovena). En verano, las calles y terrazas bulle de vida, mientras que en primavera y oto\xf1o, la ciudad antigua respira con calma. El motivo m\xe1s fotografiado es la peque\xf1a isla de Sveti Stefan, con su antiguo pueblo de pescadores convertido en hotel.",highlights:["Ciudad Antigua de Budva","Playa de Mogren","Sveti Stefan","Playa de Jaz"],activities:["Paseo por el casco antiguo","Nadar en Mogren","Vista panor\xe1mica de Sveti Stefan","Noches en la costa"],duration:"1-2 d\xedas"},podgorica:{tagline:"Relajada capital donde se encuentran r\xedos y monta\xf1as",description:"Podgorica es la capital y ciudad m\xe1s grande de Montenegro, construida en la confluencia de los r\xedos Morača y Ribnica. Su ritmo lo marcan el paseo del korzo, las terrazas de cafeter\xedas y el Puente del Milenio; Stara Varoš conserva restos de la ciudad otomana con su torre del reloj. Una excelente base de partida —el Lago de Skadar, Budva y Durmitor son todas excursiones de un d\xeda.",highlights:["Puente del Milenio","Stara Varoš","Torre del reloj","Gorica"],activities:["Paseo por el korzo","Explorar Stara Varoš","Caf\xe9 junto al Morača","Excursi\xf3n al Lago de Skadar"],duration:"1 d\xeda"},durmitor:{tagline:"UNESCO masivo sobre el lago Negro y el ca\xf1\xf3n del Tara",description:"El Parque Nacional Durmitor es una cadena monta\xf1osa surcada por 18 lagos glaciares, siendo el m\xe1s conocido el Lago Negro, situado junto a Žabljak, la capital de la monta\xf1a de la regi\xf3n. El ca\xf1\xf3n del r\xedo Tara es el m\xe1s profundo de Europa (1.300 m) y es el hogar del rafting entre sus orillas boscosas; la carretera panor\xe1mica a trav\xe9s del puerto de Sedlo conecta Žabljak con el sur. En invierno, las pistas de esqu\xed; en verano, senderos de senderismo alrededor de los lagos.",highlights:["Lago Negro","Ca\xf1\xf3n del Tara","Žabljak","Puerto de Sedlo"],activities:["Paseo alrededor del Lago Negro","Rafting por el Tara","Conducci\xf3n panor\xe1mica por el puerto de Sedlo","Esqu\xed en invierno"],duration:"2-3 d\xedas"},tirana:{tagline:"Colorida capital con n\xfacleo otomano y ritmo de cafeter\xedas",description:"Tirana es una capital que se abri\xf3 tras d\xe9cadas de aislamiento — fachadas de colores, la plaza Skanderbeg con la mezquita Et'hem Bey y el reloj de la torre, cafeter\xedas en las calles de bloques. El telef\xe9rico Dajti Ekspres sube a 1600 m sobre la ciudad para una vista sobre la llanura y el Adri\xe1tico; el museo Bunk'Art en un refugio nuclear narra la historia del siglo XX.",highlights:["Plaza Skanderbeg","Mezquita Et'hem Bey","Bunk'Art","Monte Dajti"],activities:["Explorar el centro","Telef\xe9rico a Dajti","Museos","Cultura de cafeter\xedas"],duration:"2 d\xedas"},berat:{tagline:"La ciudad de las mil ventanas debajo del castillo",description:"Berat es una ciudad protegida por la UNESCO, conocida como la ciudad de las mil ventanas: las casas otomanas blancas en la colina de Mangalem se escalonan hacia el castillo en la cima. El viejo puente sobre el r\xedo Osum conecta el barrio de Gorica; dentro del castillo se encuentra el museo de Onufri con sus iconos. Los vi\xf1edos rodean Berat, y los locales ofrecen degustaciones en casas tradicionales.",highlights:["Castillo de Berat","Barrio de Mangalem","Puente Viejo","Museo de Onufri"],activities:["Paseo por Mangalem","Visita al castillo","Puente sobre el Osum","Degustaci\xf3n de vinos"],duration:"1 d\xeda"},gjirokaster:{tagline:"Ciudad de piedra — tejados grises bajo un imponente castillo",description:"Gjirokastra es una ciudad patrimonio de la UNESCO, famosa por sus casas de piedra con tejados de pizarra, construida en una empinada ladera bajo uno de los mayores castillos de los Balcanes. El viejo bazar conserva una calle comercial otomana con arcos; la casa natal del escritor Ismail Kadare es hoy un museo. Las monta\xf1as que rodean la ciudad invitan a hacer senderismo por el valle.",highlights:["Castillo de Gjirokastra","Viejo bazar","Casas de piedra","Casa de Kadare"],activities:["Visita al castillo","Paseo por el bazar","Museo etnogr\xe1fico","Senderismo por los alrededores"],duration:"1 d\xeda"},saranda:{tagline:"Soleada ciudad jonia frente a Corf\xfa",description:"Saranda es la ciudad costera m\xe1s meridional de Albania, situada frente a la isla griega de Corf\xfa (trayecto en ferry de 30 minutos). La costa al sur de la ciudad esconde Ksamil con sus playas blancas e islotes; mientras que tierra adentro yace la antig\xfcedad — Butrint, ciudad antigua de la UNESCO entre un lago y un canal. La fortaleza de L\xebkur\xebsi, sobre la ciudad, enmarca el atardecer sobre el mar J\xf3nico.",highlights:["Ksamil","Antigua Butrint","Fortaleza de L\xebkur\xebsi","Vista de Corf\xfa"],activities:["Nadar en Ksamil","Visita a Butrint","Atardecer desde L\xebkur\xebsi","Ferry a Corf\xfa"],duration:"2-3 d\xedas"}};function r(e){return n[e]??null}},58127:(e,a,i)=>{i.d(a,{gu:()=>t,yJ:()=>n});let n="2026-09-20",r={postojna:{source:"postojnska-jama.eu",sourceUrl:"https://www.postojnska-jama.eu",verifiedAt:"2026-09-14"},kobarid:{source:"kobariski-muzej.si",sourceUrl:"https://www.kobariski-muzej.si",verifiedAt:"2026-09-14"},vintgar:{source:"vintgar.si",sourceUrl:"https://www.vintgar.si",verifiedAt:"2026-09-14"},ptuj:{source:"pmpo.si",sourceUrl:"https://www.pmpo.si",verifiedAt:"2026-09-14"},celje:{source:"visitcelje.eu",sourceUrl:"https://www.visitcelje.eu",verifiedAt:"2026-09-14"},bled:{source:"slovenia.info (STO)",sourceUrl:"https://www.slovenia.info/en/places-to-go/regions/alpine-slovenia/bled",verifiedAt:"2026-09-25"},ljubljana:{source:"slovenia.info (STO)",sourceUrl:"https://www.slovenia.info/en/places-to-go/regions/ljubljana-central-slovenia/ljubljana",verifiedAt:"2026-09-25"},piran:{source:"slovenia.info (STO)",sourceUrl:"https://www.slovenia.info/en/places-to-go/attractions/piran-and-salt-pans",verifiedAt:"2026-09-25"},soca:{source:"slovenia.info (STO)",sourceUrl:"https://www.slovenia.info/en/places-to-go/attractions/soca-valley",verifiedAt:"2026-09-25"}};function t(e){let a=r[e.id];return a?{kind:"official",source:a.source,sourceUrl:a.sourceUrl,verifiedAt:a.verifiedAt}:{kind:"internal",source:"Discover Slovenia — uredniška kuracija",verifiedAt:n}}},94286:(e,a,i)=>{i.d(a,{D:()=>r});let n={bled:{tagline:"Perle des Alpes avec son ch\xe2teau m\xe9di\xe9val et son \xeele",description:"Le lac de Bled, avec son \xeele unique sur laquelle se dresse une \xe9glise avec son clocher, est la vue la plus embl\xe9matique de la Slov\xe9nie. Le ch\xe2teau m\xe9di\xe9val perch\xe9 sur une falaise offre des panoramas \xe0 couper le souffle, tandis que la gorge de Vintgar propose une promenade courte \xe0 travers un calcaire le long d'une rivi\xe8re tranquille. Une part de g\xe2teau \xe0 la cr\xe8me (kremšnita) dans une p\xe2tisserie au bord du lac est le p\xe9ch\xe9 mignon obligatoire.",highlights:["L'\xeele de Bled","Le ch\xe2teau de Bled","La gorge de Vintgar","La kremšnita"],activities:["Balade en pletna jusqu'\xe0 l'\xeele","Visite du ch\xe2teau","Promenade dans la gorge","Baignade"],duration:"1-2 jours"},bohinj:{tagline:"Sauvage et intouchable, la beaut\xe9 du parc national du Triglav",description:"Le lac de Bohinj est le grand fr\xe8re sauvage du lac de Bled, nich\xe9 au cœur du parc national du Triglav. Le t\xe9l\xe9ph\xe9rique de Vogel offre des panoramas sur les Alpes juliennes, et la cascade Savica se reached par une courte randonn\xe9e en for\xeat. Id\xe9al pour ceux qui recherchent la tranquillit\xe9 et une immersion active dans la nature.",highlights:["Lac de Bohinj","Vogel","Cascade Savica","Parc national du Triglav"],activities:["Randonn\xe9e","Ski","Kayak","T\xe9l\xe9ph\xe9rique de Vogel"],duration:"1-2 jours"},ljubljana:{tagline:"Une capitale verte et cr\xe9ative avec le Pont du Dragon",description:"Ljubljana est une petite capitale anim\xe9e o\xf9 l'architecture m\xe9di\xe9vale se marie \xe0 une sc\xe8ne culinaire contemporaine. Le ch\xe2teau de Ljubljana offre des vues panoramiques, la place Prešeren avec le Pont du Dragon est le cœur battant de la ville, et les rives de la Ljubljanica s'animent avec le caf\xe9 et les conversations.",highlights:["Ch\xe2teau de Ljubljana","Pont du Dragon","Place Prešeren","Parc Tivoli"],activities:["Visite du ch\xe2teau","Promenade dans la vieille ville","Tour gastronomique","Cyclisme le long de la Ljubljanica"],duration:"2 jours"},postojna:{tagline:"24 km de galeries souterraines et un royaume f\xe9erique de stalactites",description:"La grotte de Postojna est le plus grand syst\xe8me de grottes touristiques d'Europe, avec son unique petit train souterrain. Elle abrite \xe9galement le prot\xe9e — un end\xe9mique qui a inspir\xe9 les l\xe9gendes sur les b\xe9b\xe9s dragons. Le ch\xe2teau de Predjama, taill\xe9 dans une falaise de 123 m\xe8tres, se trouve \xe0 seulement 9 km de l\xe0.",highlights:["Petit train souterrain","Stalactites","Prot\xe9e (poisson humain)","Ch\xe2teau de Predjama"],activities:["Visite de la grotte en train","Visite du ch\xe2teau de Predjama","Photographie"],duration:"1 jour"},piran:{tagline:"La Venise slov\xe8ne avec ses ruelles pav\xe9es et la place Tartini",description:"Piran est une petite ville c\xf4ti\xe8re de style v\xe9nitien, o\xf9 les ruelles \xe9troites s'entrem\xealent entre des maisons en pierre. La place Tartini, la place principale avec ses pav\xe9s en marbre, est d\xe9di\xe9e au violoniste Giuseppe Tartini. L'\xe9glise Saint-Georges sur la colline surplombe la mer Adriatique.",highlights:["Place Tartini","\xc9glise Saint-Georges","Le front de mer","Vieilles ruelles"],activities:["Balade dans la vieille ville","Admirer le coucher de soleil","D\xe9gustation de fruits de mer","Visite des salines"],duration:"1 jour"},soca:{tagline:"Une \xe9meraude des Alpes Juliennes pour des aventures adr\xe9nalinesques",description:"La Soča est l'une des rares rivi\xe8res \xe0 conserver sa couleur \xe9meraude toute l'ann\xe9e. Elle serpente \xe0 travers Tolmin et Bovec, offrant un rafting, du kayak et du canyoning de premier ordre. En chemin, les gorges de la Soča — des piscines naturelles sculpt\xe9es dans le calcaire, parfaites pour se rafra\xeechir en \xe9t\xe9.",highlights:["Gorges de la Soča","Bovec","Tolmin","Forteresse de Kluže"],activities:["Rafting","Kayak","Canyoning","Tyrolienne"],duration:"2-3 jours"},triglav:{tagline:"Symbole national \xe0 2 864 m avec d'innombrables sentiers",description:"Le Triglav est le plus haut sommet de Slov\xe9nie et un symbole national qui figure m\xeame sur les armoiries du pays. L'ascension demande une randonn\xe9e technique, mais avec une bonne pr\xe9paration, elle est r\xe9alisable en un ou deux jours. Au sommet se dresse la tour d'Aljaž — le plus haut refuge du pays.",highlights:["Sommet \xe0 2 864 m","Tour d'Aljaž","Rose du Triglav","Randonn\xe9e"],activities:["Randonn\xe9e","Alpinisme","Photographie"],duration:"2 jours"},kobarid:{tagline:"Histoire, fronti\xe8re de l'Isonzo et gastronomie dans un m\xeame village",description:"Kobarid est un petit village situ\xe9 sur la rivi\xe8re Soča, c\xe9l\xe8bre pour son mus\xe9e qui documente le sanglant front de l'Isonzo de la Premi\xe8re Guerre mondiale. Le pont Napol\xe9on sur la Soča et la cr\xeate de Kolovrat offrent des vues panoramiques. La maison Franko, l'une des meilleures restaurants de la r\xe9gion, sert une cuisine contemporaine du Tolmin.",highlights:["Mus\xe9e de Kobarid","Pont Napol\xe9on","Kolovrat","Maison Franko"],activities:["Visite du mus\xe9e","Randonn\xe9e","Exp\xe9rience culinaire","Cyclisme le long de la Soča"],duration:"1 jour"},maribor:{tagline:"La deuxi\xe8me plus grande ville de Slov\xe9nie, berceau de la plus vieille vigne du monde",description:"Maribor s'\xe9tend le long de la Drave, entour\xe9e des vignobles de Pohorje. La Vigne Vieille, \xe2g\xe9e de plus de 400 ans, est inscrite dans le Livre des records Guinness. La ville propose un centre-ville anim\xe9, les coteaux viticoles de Pohorje et des sports d'hiver.",highlights:["La Vigne Vieille","Pohorje","Place principale","Viticulture"],activities:["Visite de la Vigne Vieille","Ski \xe0 Pohorje","D\xe9gustation de vins","Promenade dans le centre historique"],duration:"1-2 jours"},portoroz:{tagline:"Station baln\xe9aire slov\xe8ne avec casino et bien-\xeatre",description:"Portorož est la station baln\xe9aire la plus c\xe9l\xe8bre de Slov\xe9nie, avec une longue plage de sable, des h\xf4tels avec centres de bien-\xeatre et un casino. La promenade en bord de mer relie Portorož \xe0 Piran, tandis que les salines de Sečovlje offrent une exp\xe9rience nature unique et des soins de bien-\xeatre \xe0 la boue th\xe9rapeutique.",highlights:["Plage","Casino","Salines de Sečovlje","Bien-\xeatre"],activities:["Baignade","Bien-\xeatre","Jeux d'argent","V\xe9lo le long de la mer"],duration:"2-3 jours"},vintgar:{tagline:"Une courte promenade \xe0 travers un calcaire bord\xe9 d'une rivi\xe8re paisible",description:"La gorge de Vintgar est un canyon de 1,6 km le long de la rivi\xe8re Radovna, \xe0 seulement 4 km de Bled. Des passerelles en bois serpentent \xe0 c\xf4t\xe9 des eaux cristallines, passant \xe0 c\xf4t\xe9 d'une cascade et de piscines naturelles. La promenade dure environ une heure et convient \xe0 tous les \xe2ges.",highlights:["Cascade de Šum","Passerelles en bois","Eau cristalline","Piscines naturelles"],activities:["Randonn\xe9e","Photographie","Observation de la nature"],duration:"1 jour"},rogaska:{tagline:"La plus ancienne station thermale de Slov\xe9nie, c\xe9l\xe8bre pour ses eaux min\xe9rales",description:"Rogaška Slatina est une station thermale \xe9l\xe9gante avec une tradition de 400 ans, r\xe9put\xe9e pour son eau min\xe9rale Donat Mg, la plus riche en magn\xe9sium au monde. L'architecture Art Nouveau, les parcs et les centres de bien-\xeatre offrent une d\xe9tente toute l'ann\xe9e.",highlights:["Donat Mg","Architecture Art Nouveau","Grand Hotel","Bien-\xeatre"],activities:["Bien-\xeatre","D\xe9gustation d'eaux min\xe9rales","Promenades dans les parcs","Massages"],duration:"2 jours"},ptuj:{tagline:"La plus ancienne ville de Slov\xe9nie avec une histoire romaine",description:"Ptuj est la plus ancienne ville enregistr\xe9e de Slov\xe9nie, fond\xe9e \xe0 l'\xe9poque romaine sous le nom de Poetovio. Le ch\xe2teau m\xe9di\xe9val sur la colline offre des vues panoramiques sur la Drava, tandis que le centre historique a conserv\xe9 son architecture baroque. Elle est c\xe9l\xe8bre pour le Kurentovanje — le plus grand festival de carnaval d'Europe centrale.",highlights:["Ch\xe2teau de Ptuj","Remp romains","Kurentovanje","Drava"],activities:["Visite du ch\xe2teau","Promenade dans la vieille ville","Festival de carnaval","Promenade le long de la Drava"],duration:"1 jour"},celje:{tagline:"Ancienne capitale des comtes de Celje avec son imposante forteresse",description:"Celje est la troisi\xe8me plus grande ville de Slov\xe9nie, c\xe9l\xe8bre pour son ch\xe2teau m\xe9di\xe9val des comtes de Celje — autrefois la dynastie noblaire la plus influente des terres slov\xe8nes. La Vieille Place conserve ses fa\xe7ades baroques, et une promenade sinueuse longe la rivi\xe8re Savinja.",highlights:["Ch\xe2teau de Celje","Vieille Place","Savinja","Mus\xe9e r\xe9gional"],activities:["Visite du ch\xe2teau","Promenade dans la vieille ville","Mus\xe9e","Cyclisme le long de la Savinja"],duration:"1 jour"},"nova-gorica":{tagline:"La ville des roses sur la fronti\xe8re italienne",description:"Nova Gorica est une jeune ville construite apr\xe8s la Seconde Guerre mondiale, connue comme la 'ville des roses'. Elle jouxte la ville italienne de Gorizia — les deux seules villes europ\xe9ennes partageant une m\xeame place (Place de l'Europe). Un casino, des parcs verdoyants et une ambiance m\xe9diterran\xe9enne compl\xe8tent le tableau.",highlights:["Place de l'Europe","Parc des roses","Casino Perla","Pont de Solkan"],activities:["Promenade dans le parc","Jeux de hasard","Promenade transfrontali\xe8re en Italie","Cyclisme le long de la Soča"],duration:"1 jour"},"slovenj-gradec":{tagline:"Une ville alpine riche en tradition musicale",description:"Slovenj Gradec est une ville historique du nord de la Slov\xe9nie, entour\xe9e par les Alpes carinthiennes. Connue pour la Salle des Musiciens slov\xe8nes et comme lieu de naissance du compositeur Hugo Wolf. C'est le point de d\xe9part id\xe9al pour des randonn\xe9es sur le Pohorje et l'Uršlja Gora.",highlights:["Salle des Musiciens slov\xe8nes","Vieille Place","Pohorje","Uršlja Gora"],activities:["Randonn\xe9e p\xe9destre","Concerts de musique","Promenade dans la vieille ville","Ski"],duration:"1 jour"},dravograd:{tagline:"Le confluent des rivi\xe8res Drave, Meža et Mislinja",description:"Dravograd est une petite ville du nord de la Slov\xe9nie o\xf9 trois rivi\xe8res — la Drave, la Meža et la Mislinja — se rejoignent. Elle est entour\xe9e par les for\xeats de Kozjak et de Pohorje. Parmi les points d'int\xe9r\xeat, on trouve une centrale hydro\xe9lectrique sur la Drave et des sentiers de randonn\xe9e le long des rives.",highlights:["Confluent de trois rivi\xe8res","Centrale hydro\xe9lectrique de Dravograd","Kozjak","Randonn\xe9e"],activities:["Randonn\xe9e","P\xeache","Cyclisme le long de la Drave","Photographie de la nature"],duration:"1 jour"},"murska-sobota":{tagline:"Le cœur de la r\xe9gion de Prekmurje avec son ch\xe2teau au bord du lac",description:"Murska Sobota est le cœur de la r\xe9gion de Prekmurje, une plaine de la Pannonie situ\xe9e dans le nord-est de la Slov\xe9nie. Le ch\xe2teau de Murska Sobota, situ\xe9 au bord du lac du m\xeame nom, abrite le Mus\xe9e r\xe9gional. La ville est connue pour sa gibanica de Prekmurje et son huile de graines de potiron.",highlights:["Ch\xe2teau de Murska Sobota","Lac de Sobota","Gibanica de Prekmurje","Mus\xe9e r\xe9gional"],activities:["Visite du ch\xe2teau","Promenade au bord du lac","Exp\xe9riences culinaires","Cyclisme dans la plaine"],duration:"1 jour"},lendava:{tagline:"Ville bilingue avec ses vignobles et son ch\xe2teau sur la colline",description:"Lendava est la ville la plus orientale de Slov\xe9nie, situ\xe9e \xe0 la fronti\xe8re hongroise. Cette ville bilingue (slov\xe8ne-hongroise) abrite un ch\xe2teau sur la colline qui offre une vue panoramique sur les vignobles des collines de Lendavske gorice. La r\xe9gion est r\xe9put\xe9e pour la production de vins blancs de grande qualit\xe9.",highlights:["Ch\xe2teau de Lendava","Vignobles des collines de Lendavske gorice","Culture bilingue","Cave \xe0 vin"],activities:["D\xe9gustation de vins","Visite du ch\xe2teau","Cyclisme \xe0 travers les vignobles","Promenade transfrontali\xe8re"],duration:"1 jour"},"novo-mesto":{tagline:"La capitale de la r\xe9gion de Dolenjska sur la rivi\xe8re Krka",description:"Novo mesto est le centre de la r\xe9gion de Dolenjska, construite dans un m\xe9andre de la rivi\xe8re Krka. La Place Vienne et sa rue principale conservent leur caract\xe8re m\xe9di\xe9val. La ville est c\xe9l\xe8bre pour son cviček — le vin traditionnel de Dolenjska — et pour ses d\xe9couvertes arch\xe9ologiques de la culture de Hallstatt.",highlights:["Place Vienne","Rivi\xe8re Krka","Cviček","Mus\xe9e arch\xe9ologique"],activities:["Promenade dans la vieille ville","D\xe9gustation de vin","Cyclisme le long de la Krka","Visite du mus\xe9e"],duration:"1-2 jours"},otocec:{tagline:"Le seul ch\xe2teau slov\xe8ne sur une \xeele fluviale",description:"Otočec est le seul ch\xe2teau slov\xe8ne situ\xe9 sur une \xeele, entour\xe9 par les eaux de la rivi\xe8re Krka. Aujourd'hui, c'est un h\xf4tel de luxe avec un terrain de golf et des installations de bien-\xeatre. Un cadre romantique pour les couples et un point de d\xe9part pour le cyclisme le long de la Krka.",highlights:["Ch\xe2teau sur l'\xeele","Rivi\xe8re Krka","Golf","Bien-\xeatre"],activities:["Golf","Bien-\xeatre","V\xe9lo le long de la Krka","D\xeener romantique"],duration:"1-2 jours"},crnomelj:{tagline:"Le cœur de la r\xe9gion de Bela krajina sur la rivi\xe8re Kolpa",description:"Črnomelj est le centre de la r\xe9gion de Bela krajina — un paysage chaud et inspir\xe9 par la M\xe9diterran\xe8re, dans le sud-est de la Slov\xe9nie, sur la rivi\xe8re Kolpa. Connue pour ses œufs de P\xe2ques peints (pisanica), la lande et la musique traditionnelle de Bela krajina. La Kolpa offre les eaux les plus chaudes pour la baignade en Slov\xe9nie.",highlights:["Rivi\xe8re Kolpa","Vieux march\xe9","Pisanica de Bela krajina","Landes"],activities:["Baignade dans la Kolpa","Promenade dans la vieille ville","V\xe9lo \xe0 travers Bela krajina","Mus\xe9e ethnographique"],duration:"1-2 jours"},zagreb:{tagline:"La capitale croate avec le charme viennois et la culture des caf\xe9s",description:"Zagreb est une ville \xe0 la crois\xe9e de l'Europe centrale et du sud-est, avec un cœur d'\xe9poque austro-hongroise : la Haute-Ville avec son march\xe9 couvert et la tour Lotrščak, les rues Art Nouveau de la Basse-Ville, et le march\xe9 anim\xe9 de Dolac le matin. Son march\xe9 de l'Avent est l'un des plus festifs d'Europe en d\xe9cembre, tandis que le caf\xe9 d'\xe9t\xe9 dans la rue Tkalčićeva rythme la ville.",highlights:["Haute-Ville","Place Ban Jelačić","March\xe9 Dolac","Cath\xe9drale"],activities:["Promenade dans la Haute-Ville","Mus\xe9es et galeries","March\xe9 de l'Avent en d\xe9cembre","Caf\xe9 dans la rue Tkalčićeva"],duration:"2 jours"},"plitvicka-jezera":{tagline:"Cascade de lacs et cascades turquoises, site UNESCO",description:"Le plus ancien parc national de Croatie est une cha\xeene de seize lacs qui se d\xe9versent les uns dans les autres au-dessus de barri\xe8res de travertin et de cascades. Des passerelles en bois longent l'eau \xe0 travers la for\xeat, et des bateaux \xe9lectriques traversent le plus grand lac, Kozjak. La couleur de l'eau passe du turquoise \xe0 l'\xe9meraude en fonction de la saison et de la lumi\xe8re.",highlights:["Grande Cascade","Lac Kozjak","Passerelles en bois","Barri\xe8res de travertin"],activities:["Promenade sur les passerelles","Croisi\xe8re sur le lac Kozjak","Photographie","Vue sur la Grande Cascade"],duration:"1 jour"},rijeka:{tagline:"Capitale culturelle avec le plus grand port de Croatie",description:"Rijeka est une ville portuaire sur le golfe de Kvarner, avec un cœur austro-hongrois, la longue promenade du Korzo et le ch\xe2teau de Trsat sur la colline surplombant la ville. Capitale europ\xe9enne de la culture en 2020, son carnaval de P\xe2ques est l'un des plus grands d'Europe. Des ferries partent de son port vers les \xeeles et l'Italie — la ville est la porte d'entr\xe9e du Kvarner.",highlights:["Korzo","Ch\xe2teau de Trsat","Tour de la ville","Cath\xe9drale Saint-Vitus"],activities:["Promenade sur le Korzo","Vue depuis Trsat","Carnaval de Rijeka","Excursions en ferry vers les \xeeles"],duration:"1-2 jours"},pula:{tagline:"Un amphith\xe9\xe2tre romain sur la mer Adriatique",description:"Pula est la plus grande ville d'Istrie, abritant le plus bel amphith\xe9\xe2tre romain au monde apr\xe8s celui de Rome — l'Arena du Ier si\xe8cle accueille encore aujourd'hui des concerts et du cin\xe9ma en plein air. Le cœur historique avec la Porte d'Or et la Cath\xe9drale Sainte-Marie s'\xe9tire sur une p\xe9ninsule, entour\xe9 de plages et de villages viticoles istriens.",highlights:["Amphith\xe9\xe2tre de l'Arena","Porte d'Or","Vieille Place","Rivi\xe8re d'Istrie"],activities:["Visite de l'Arena","Promenade dans la vieille ville","Baignade","D\xe9gustation de vins d'Istrie"],duration:"1-2 jours"},zadar:{tagline:"La ville des couchers de soleil et des orgues marines",description:"Zadar est une ville dalmate sur une p\xe9ninsule, dot\xe9e d'un plan en damier romain et de l'\xe9glise romane Saint-Donat. Sur le front de mer, les orgues marines jouent avec les vagues, \xe0 c\xf4t\xe9 du Salut au Soleil — une installation qui attire les foules au cr\xe9puscule ; Alfred Hitchcock a qualifi\xe9 le coucher de soleil de Zadar de plus beau du monde. Les \xeeles Kornati sont les plus proches \xe0 partir d'ici.",highlights:["Les orgues marines","Le Salut au Soleil","L'\xe9glise Saint-Donat","Les ruines romaines"],activities:["\xc9couter les orgues marines","Admirer le coucher de soleil","Se promener sur les remparts","Excursion aux \xeeles Kornati"],duration:"1-2 jours"},split:{tagline:"Une ville vivante au sein du palais de Diocl\xe9tien",description:"Le cœur de Split est le palais de Diocl\xe9tien du IVe si\xe8cle — un complexe romain o\xf9 des gens vivent encore : des caf\xe9s sur le P\xe9ristyle, un march\xe9 dans les caves, des boutiques dans les halls vo\xfbt\xe9s. La cath\xe9drale Saint-Duje est la plus vieille cath\xe9drale du monde en utilisation continue. La colline de Marjan offre une \xe9chapp\xe9e dans les pins surplombant la ville, et des ferries partent du port vers les \xeeles.",highlights:["Palais de Diocl\xe9tien","P\xe9ristyle","Cath\xe9drale Saint-Duje","Marjan"],activities:["Explorer le palais","Promenade sur Marjan","Plage de Bačvice","Excursions en ferry vers les \xeeles"],duration:"2 jours"},hvar:{tagline:"L'\xeele la plus ensoleill\xe9e de la mer Adriatique, de la lavande et du vin",description:"Hvar jouit de pr\xe8s de 2 800 heures de soleil par an, d'une ville portuaire d'inspiration v\xe9nitienne et de la forteresse Fortica sur la colline. L'int\xe9rieur de l'\xeele abrite des champs de lavande et des vignobles de pošip (un c\xe9page local). En face du port s'\xe9tendent les \xeeles Pakleni — des criques rocheuses parfaites pour mouiller et nager.",highlights:["Forteresse Fortica","Port d'Hvar","\xceles Pakleni","Champs de lavande"],activities:["Vue depuis Fortica","Excursion aux \xeeles Pakleni","D\xe9gustation de vin pošip","Baignade dans les criques"],duration:"2-3 jours"},dubrovnik:{tagline:"Cit\xe9 m\xe9di\xe9vale fortifi\xe9e au-dessus de l'Adriatique bleue",description:"Dubrovnik — la r\xe9publique de Raguse qui rivalisa avec Venise pendant des si\xe8cles — est une ville fortifi\xe9e qui s'\xe9l\xe8ve de la mer, dont la Stradun relie les portes de Pile et de Ploče. Le parcours sur le mur, long de pr\xe8s de deux kilom\xe8tres, est la plus c\xe9l\xe8bre promenade urbaine de l'Adriatique ; un t\xe9l\xe9ph\xe9rique grimpe jusqu'\xe0 Srđ pour offrir une vue sur la vieille ville et les \xeeles. L'\xeele bois\xe9e de Lokrum se trouve juste au large.",highlights:["Les remparts de la ville","La Stradun","L'\xeele de Lokrum","Le t\xe9l\xe9ph\xe9rique de Srđ"],activities:["Promenade sur les remparts","Le clo\xeetre du monast\xe8re franciscain","Excursion \xe0 Lokrum","Le coucher du soleil depuis Srđ"],duration:"2-3 jours"},kotor:{tagline:"Une baie de type fjord avec une ville m\xe9di\xe9vale fortifi\xe9e",description:"Kotor est nich\xe9 au fond de la baie de Kotor, qui sinue entre des montagnes escarp\xe9es, comme le seul fjord de la M\xe9diterran\xe9e. La vieille ville, inscrite au patrimoine de l'UNESCO, se pr\xe9sente comme un labyrinthe de places et de ruelles ; les remparts du ch\xe2teau San Giovanni s'\xe9l\xe8vent \xe0 plus de 1200 marches au-dessus de la ville pour offrir une vue l\xe9gendaire sur la baie. \xc0 proximit\xe9, \xe0 Perast, se trouve l'\xeelot baroque Notre-Dame du Rocheau.",highlights:["Vieille ville de Kotor","Remparts de San Giovanni","Baie de Kotor","Perast"],activities:["Promenade dans la vieille ville","Escalade des remparts","Excursion \xe0 Perast","Croisi\xe8re dans la baie"],duration:"1-2 jours"},budva:{tagline:"Une vieille ville sur une p\xe9ninsule entre plages et pins",description:"Budva est la station baln\xe9aire la plus visit\xe9e du Mont\xe9n\xe9gro — un noyau historique sur une p\xe9ninsule rocheuse et fortifi\xe9e, entour\xe9e de plages (Mogren, Jaz, Slovenska plaža). En \xe9t\xe9, les rues et les terrasses sont bond\xe9es ; au printemps et en automne, la vieille ville respire la d\xe9tente. Le site le plus photographi\xe9 est l'\xeelot de Sveti Stefan, avec son ancien village de p\xeacheurs transform\xe9 en h\xf4tel.",highlights:["Ville vieille de Budva","Plage de Mogren","Sveti Stefan","Plage de Jaz"],activities:["Balade dans la vieille ville","Baignade \xe0 Mogren","Vue sur Sveti Stefan","Soir\xe9es au bord de l'eau"],duration:"1-2 jours"},podgorica:{tagline:"La capitale d\xe9tendue o\xf9 rivi\xe8res et montagnes se rencontrent",description:"Podgorica est la capitale et la plus grande ville du Mont\xe9n\xe9gro, construite au confluent des rivi\xe8res Morača et Ribnica. Le rythme de la ville est rythm\xe9 par le korzo, les terrasses de caf\xe9s et le pont du Mill\xe9naire ; la vieille ville (Stara Varoš) conserve les vestiges de la ville ottomane avec sa tour \xe0 horloge. Un excellent point de d\xe9part — le lac de Skadar, Budva et le Durmitor sont tous accessibles pour des excursions d'une journ\xe9e.",highlights:["Pont du Mill\xe9naire","Stara Varoš (vieille ville)","Tour \xe0 l'horloge","Colline de Gorica"],activities:["Promenade sur le korzo","Exploration de la vieille ville (Stara Varoš)","Caf\xe9 au bord de la Morača","Excursion au lac de Skadar"],duration:"1 jour"},durmitor:{tagline:"UNESCO massif au-dessus du lac de Crno et du canyon de la Tara",description:"Le parc national du Durmitor est un massif montagneux parsem\xe9 de 18 lacs glaciaires — le plus c\xe9l\xe8bre \xe9tant le lac de Crno, pr\xe8s de Žabljak, la capitale des montagnes de la r\xe9gion. Le canyon de la rivi\xe8re Tara est le plus profond d'Europe (1 300 m) et abrite du rafting entre ses rives bois\xe9es ; la route panoramique par le col de Sedlo relie Žabljak au sud. En hiver, les pistes de ski sont ouvertes, tandis qu'en \xe9t\xe9, des sentiers de randonn\xe9e serpentent autour des lacs.",highlights:["Lac de Crno","Canyon de la Tara","Žabljak","Col de Sedlo"],activities:["Randonn\xe9e autour du lac de Crno","Rafting sur la Tara","Route panoramique par le col de Sedlo","Ski en hiver"],duration:"2-3 jours"},tirana:{tagline:"Une capitale color\xe9e avec un noyau ottoman et un rythme caf\xe9",description:"Tirana est une capitale qui s'est ouverte apr\xe8s des d\xe9cennies de fermeture — fa\xe7ades color\xe9es, place Skanderbeg avec la mosqu\xe9e Et'hem Bey et la tour de l'horloge, caf\xe9s dans les rues de blocs. Le t\xe9l\xe9ph\xe9rique Dajti Ekspres grimpe \xe0 1 600 m au-dessus de la ville pour une vue sur la plaine et l'Adriatique ; le mus\xe9e Bunk'Art, install\xe9 dans un abri antiatomique, raconte l'histoire du XXe si\xe8cle.",highlights:["Place Skanderbeg","Mosqu\xe9e Et'hem Bey","Bunk'Art","Montagne Dajti"],activities:["Explorer le centre","T\xe9l\xe9ph\xe9rique de Dajti","Mus\xe9es","Culture caf\xe9"],duration:"2 jours"},berat:{tagline:"La ville aux mille fen\xeatres sous le ch\xe2teau",description:"Berat est une ville prot\xe9g\xe9e par l'UNESCO, connue comme la ville aux mille fen\xeatres — les maisons ottomanes blanches sur la colline de Mangalem s'\xe9l\xe8gent en escalier vers le ch\xe2teau au sommet. Le vieux pont sur la rivi\xe8re Osum relie le quartier de Gorica ; \xe0 l'int\xe9rieur du ch\xe2teau se trouve le mus\xe9e Onufri avec ses ic\xf4nes. Autour de Berat s'\xe9tendent des vignobles, o\xf9 les habitants proposent des d\xe9gustations dans des maisons traditionnelles.",highlights:["Ch\xe2teau de Berat","Quartier Mangalem","Vieux pont","Mus\xe9e Onufri"],activities:["Promenade dans Mangalem","Visite du ch\xe2teau","Pont sur l'Osum","D\xe9gustation de vin"],duration:"1 jour"},gjirokaster:{tagline:"La cit\xe9 de pierre — toits gris sous un ch\xe2teau majestueux",description:"Gjirokast\xebr est une ville class\xe9e UNESCO, c\xe9l\xe8bre pour ses maisons en pierre et toits en ardoise, construite sur un escarpement sous l'un des plus grands ch\xe2teaux des Balkans. L'ancienne bazar conserve une rue commerciale ottomane avec des arcades ; la maison natale de l'\xe9crivain Ismail Kadare est aujourd'hui un mus\xe9e. Les montagnes environnantes invitent \xe0 des randonn\xe9es au-dessus de la vall\xe9e.",highlights:["Ch\xe2teau de Gjirokast\xebr","Ancien bazar","Maisons en pierre","Maison de Kadare"],activities:["Visite du ch\xe2teau","Promenade dans le bazar","Mus\xe9e ethnographique","Randonn\xe9es dans les environs"],duration:"1 jour"},saranda:{tagline:"Une ville ensoleill\xe9e de la mer Ionienne, en face de Corfou",description:"Saranda est la ville c\xf4ti\xe8re la plus m\xe9ridionale d'Albanie, en face de l'\xeele grecque de Corfou (trajet en ferry de 30 minutes). La c\xf4te au sud de la ville abrite Ksamil avec ses plages de sable blanc et ses \xeelots ; \xe0 l'int\xe9rieur des terres se trouve l'antiquit\xe9 — Butrint, une ancienne ville class\xe9e UNESCO, situ\xe9e entre un lac et un canal. La forteresse de L\xebkur\xebsi, surplombant la ville, offre un cadre magnifique pour admirer le coucher de soleil sur la mer Ionienne.",highlights:["Ksamil","Butrint antique","Forteresse de L\xebkur\xebsi","Vue sur Corfou"],activities:["Baignade \xe0 Ksamil","Visite de Butrint","Coucher de soleil depuis L\xebkur\xebsi","Ferry pour Corfou"],duration:"2-3 jours"}};function r(e){return n[e]??null}}}]);